#include <stdio.h>
#include <stdint.h>
#include <string.h>
static int N[200];
static void load(void){
  FILE*f=fopen("/tmp/t/noise.txt","r"); if(!f){exit(1);} 
  int i=0; char c; int v=0; int sign=1;
  while((c=fgetc(f))!=EOF){
    if(c=='-') sign=-1;
    else if(c>='0'&&c<='9'){ v=v*10+(c-'0'); }
    else { if(sign<0||v) { if(i<200) N[i++]=sign*v; } sign=1; v=0; }
  }
  fclose(f);
}
static int nlen=100;

/* check helper */
static int chk(int ok, uint64_t r, int k){
  /* given two 32-bit halves a,b from r */
  uint32_t a=r>>32, b=(uint32_t)r;
  uint64_t s=(uint64_t)a+b;
  int n;
  if(s < 0x80000000ULL) n=-1;
  else if(s < 0x180000000ULL) n=0;
  else n=1;
  return n==N[k];
}

typedef uint64_t(*rngfn)(uint64_t*);
static uint64_t xs64(uint64_t*s){ uint64_t x=*s; x^=x<<13; x^=x>>7; x^=x<<17; *s=x; return x;}
static uint64_t xs64s(uint64_t*s){ uint64_t x=*s; x^=x>>12; x^=x<<25; x^=x>>27; *s=x; return x*2685821657736338717ULL;}
static uint64_t sm64(uint64_t*s){ uint64_t z=(*s+=0x9E3779B97F4A7C15ULL); z=(z^(z>>30))*0xBF58476D1CE4E5B9ULL; z=(z^(z>>27))*0x94D049BB133111EBULL; return z^(z>>31);}
static uint64_t lcg(uint64_t*s){ *s = *s*6364136223846793005ULL + 1442695040888963407ULL; return *s;}
static uint64_t pcg(uint64_t*s){ uint64_t st=*s; *s=st*6364136223846793005ULL+1442695040888963407ULL; uint64_t xo=st^(*s>>18); return ((xo>>27)+(xo>>31))>>32;}
static uint64_t xs2(uint64_t*s){ uint64_t x=*s; x^=x<<13;x^=x>>17;x^=x<<5; *s=x; return x;} /* xorshift64 variant */

int main(int argc,char**argv){ load();
  struct {const char*name; rngfn f;} fns[]={
    {"xorshift13_7_17",xs64},{"xorshift64*",xs64s},{"splitmix64",sm64},{"lcg64",lcg},{"pcg32like",pcg},{"xorshift5_17_13",xs2}
  };
  int nfn=sizeof(fns)/sizeof(fns[0]);
  for(int fi=0; fi<nfn; fi++){
    uint64_t lim = strtoull(argv[1],0,0);
    for(uint64_t s0=0;s0<lim;s0++){
      uint64_t s=s0; int ok=1;
      for(int k=0;k<nlen;k++){
        uint64_t r=fns[k?1:1](&s); /* placeholder */
        (void)k; (void)r;
      }
      (void)ok;
    }
  }
  /* do properly below */
  return 0;
}
