    case SOX_ENCODING_OKI_ADPCM: return bits == 4 ? 12 : 0;
    case SOX_ENCODING_CVSD:      return bits == 1 ? 16 : 0;
    case SOX_ENCODING_LPC10:     return bits == 0 ? 16 : 0;
    case SOX_ENCODING_HCOM:      return bits == 8 ? 8 : 0;
