  {"Floating Point (text) PCM", SOX_ENCODING_FLOAT_TEXT, 54, 0},
  {"HCOM",                      SOX_ENCODING_HCOM,     8,  8},
};

static const struct { char const *name; sox_encoding_t e; } opt_enc_names[] = {
  {"signed-integer",  SOX_ENCODING_SIGNED},
  {"unsigned-integer",SOX_ENCODING_UNSIGNED},
  {"floating-point",  SOX_ENCODING_FLOAT},
  {"ms-adpcm",        SOX_ENCODING_MS_ADPCM},
  {"ima-adpcm",       SOX_ENCODING_IMA_ADPCM},
  {"oki-adpcm",       SOX_ENCODING_OKI_ADPCM},
  {"gsm-full-rate",   SOX_ENCODING_GSM_FULL_RATE},
  {"u-law",           SOX_ENCODING_ULAW},
  {"mu-law",          SOX_ENCODING_ULAW},
  {"a-law",           SOX_ENCODING_ALAW},
};

char const *sox_encoding_name(sox_encoding_t e)
{
  size_t i;
  for (i = 0; i < sizeof(enc_names)/sizeof(enc_names[0]); ++i)
    if (enc_names[i].e == e) return enc_names[i].name;
  return "Unknown";
}

/* Find an encoding by name: case insensitive prefix match, must be unique. */
sox_encoding_t sox_find_encoding(char const *name)
{
  size_t i, n = sizeof(opt_enc_names)/sizeof(opt_enc_names[0]);
  size_t len = strlen(name);
  int count = 0;
  sox_encoding_t found = SOX_ENCODING_UNKNOWN;
  for (i = 0; i < n; ++i)
    if (strncaseeq(opt_enc_names[i].name, name, len)) { ++count; found = opt_enc_names[i].e; }
