    case SOX_ENCODING_FLOAT:
    case SOX_ENCODING_FLOAT_TEXT:
      return precision == 54 ? 64 : (precision == 25 ? 32 : 0);
    case SOX_ENCODING_ULAW:  return 8;
    case SOX_ENCODING_ALAW:  return 8;
    case SOX_ENCODING_IMA_ADPCM: return 4;
    case SOX_ENCODING_MS_ADPCM:  return 4;
    case SOX_ENCODING_OKI_ADPCM: return 4;
    case SOX_ENCODING_CVSD: return 1;
    case SOX_ENCODING_LPC10: return 0;
    case SOX_ENCODING_HCOM: return 8;
    default: return 0;
  }
}

/* Resolve (encoding, bits) to a precision; returns 0 when the combination is invalid. */
unsigned sox_precision_for(sox_encoding_t e, unsigned bits)
{
  switch (e) {
    case SOX_ENCODING_SIGNED:   return bits >= 1 && bits <= 32 ? bits : 0;
    case SOX_ENCODING_UNSIGNED: return (bits == 8 || bits == 16 || bits == 24 || bits == 32) ? bits : 0;
    case SOX_ENCODING_FLOAT:    return bits == 32 ? 25 : bits == 64 ? 54 : 0;
    case SOX_ENCODING_FLOAT_TEXT: return bits == 0 ? 54 : 0;
    case SOX_ENCODING_ULAW:     return bits == 8 ? 14 : 0;
    case SOX_ENCODING_ALAW:     return bits == 8 ? 13 : 0;
    case SOX_ENCODING_IMA_ADPCM: return bits == 4 ? 13 : 0;
    case SOX_ENCODING_MS_ADPCM:  return bits == 4 ? 14 : 0;
    case SOX_ENCODING_OKI_ADPCM: return bits == 4 ? 12 : 0;
    case SOX_ENCODING_CVSD:      return bits == 1 ? 16 : 0;
    case SOX_ENCODING_LPC10:     return bits == 0 ? 16 : 0;
    case SOX_ENCODING_HCOM:      return bits == 8 ? 8 : 0;
    default: return 0;
  }
}

/* Default bits for an encoding when -b is not supplied. */
unsigned sox_default_bits(sox_encoding_t e)
{
  switch (e) {
    case SOX_ENCODING_ULAW: case SOX_ENCODING_ALAW: return 8;
    case SOX_ENCODING_IMA_ADPCM: case SOX_ENCODING_MS_ADPCM: case SOX_ENCODING_OKI_ADPCM: return 4;
    default: return 0;
  }
}
