/* ---------------- A-law / mu-law ---------------- */

static int ulaw16(unsigned char b)
{
  b = ~b;
  int t = ((b & 0x0F) << 3) + 0x84;
  t <<= (b & 0x70) >> 4;
  return (b & 0x80) ? (0x84 - t) : (t - 0x84);
}

static int alaw16(unsigned char b)
{
  b ^= 0x55;
  int t = (b & 0x0F) << 4;
  int seg = (b & 0x70) >> 4;
  switch (seg) {
    case 0: t += 8; break;
    default: t += 0x108; if (seg > 1) t <<= seg - 1; break;
  }
  return (b & 0x80) ? t : -t;
}

