/* IMA ADPCM decode of one nibble */
int sox_ima_decode_nibble(int code, int *index, int *val)
{
  int step = ima_step_table[*index];
  int diff = step >> 3;
  if (code & 4) diff += step;
  if (code & 2) diff += step >> 1;
  if (code & 1) diff += step >> 2;
  if (code & 8) diff = -diff;
