  sox_size_t outlen;
  sox_uint64_t written_blocks;
  int fact_written;
} wav_t;

#define W ((wav_t*)ft->priv)

static int wav_startread(sox_format_t *ft)
{
  unsigned char id[4];
  uint32_t len;
  wav_t *w;
  if (fread(id,1,4,ft->fp) != 4) return SOX_EOF;
  if (memcmp(id,"RIFF",4) == 0) w = NULL;
  else if (memcmp(id,"RIFX",4) == 0) w = NULL;
  else return SOX_EOF;
  (void)w;
  ft->priv = calloc(1, sizeof(wav_t));
  {
    int be = memcmp(id,"RIFX",4) == 0;
    uint32_t riff;
    unsigned char wave[4];
    if (be) { if (rd4b(ft->fp,&riff)) return SOX_EOF; }
    else { if (rd4l(ft->fp,&riff)) return SOX_EOF; }
    if (fread(wave,1,4,ft->fp) != 4) return SOX_EOF;
    if (memcmp(wave, be ? "EVAW" : "WAVE", 4) != 0) return SOX_EOF;
    W->is_be = be;
    for (;;) {
      unsigned char cid[4];
      if (fread(cid,1,4,ft->fp) != 4) return SOX_EOF;
      if (be) { if (rd4b(ft->fp,&len)) return SOX_EOF; } else { if (rd4l(ft->fp,&len)) return SOX_EOF; }
      if (memcmp(cid, be ? " TMF" : "fmt ", 4) == 0) {
        if (be) { if (rd2b(ft->fp,(uint32_t*)&W->format)) return SOX_EOF; }
        else { if (rd2l(ft->fp,(uint32_t*)&W->format)) return SOX_EOF; }
        if (be) { if (rd2b(ft->fp,&W->ch)) return SOX_EOF; if (rd4b(ft->fp,&W->rate)) return SOX_EOF;
                  if (rd4b(ft->fp,&W->brate)) return SOX_EOF; if (rd2b(ft->fp,&W->blk)) return SOX_EOF;
                  if (rd2b(ft->fp,&W->bits)) return SOX_EOF; }
        else { if (rd2l(ft->fp,&W->ch)) return SOX_EOF; if (rd4l(ft->fp,&W->rate)) return SOX_EOF;
               if (rd4l(ft->fp,&W->brate)) return SOX_EOF; if (rd2l(ft->fp,&W->blk)) return SOX_EOF;
               if (rd2l(ft->fp,&W->bits)) return SOX_EOF; }
        if (len > 16) {
          unsigned n = len - 16;
          unsigned char ext[64];
          if (n > 64) { fseek(ft->fp, n - 64, SEEK_CUR); n = 64; }
          if (fread(ext,1,n,ft->fp) != n) return SOX_EOF;
          if (W->format == 0xFFFE && n >= 24) {
            unsigned sub = ext[0] | (ext[1] << 8);
            W->format = sub;
          } else if (W->format == 2 && n >= 4) {
            W->cb = ext[0] | (ext[1] << 8);
            W->spb = ext[2] | (ext[3] << 8);
            if (n >= 6) { W->ncoef = ext[4] | (ext[5] << 8);
              memcpy(W->coefs, ext + 6, n - 6 > 28 ? 28 : n - 6); }
          } else if (W->format == 17 && n >= 2) {
            W->cb = ext[0] | (ext[1] << 8);
            if (n >= 4) W->spb = ext[2] | (ext[3] << 8);
          }
        }
      } else if (memcmp(cid, be ? "ATAD" : "data", 4) == 0) {
        W->dataoff = ftell(ft->fp);
        W->datalen = len;
        break;
      } else if (memcmp(cid, be ? "TCAF" : "fact", 4) == 0) {
        uint32_t v;
        if (be) rd4b(ft->fp,&v); else rd4l(ft->fp,&v);
        W->samples = v;
        if (len > 4) fseek(ft->fp, len - 4, SEEK_CUR);
      } else if (memcmp(cid, be ? "TSIL" : "LIST", 4) == 0) {
        unsigned char t[4];
        unsigned left = len;
        if (fread(t,1,4,ft->fp)!=4) return SOX_EOF;
        left -= 4;
        if (memcmp(t, be ? "OFNI" : "INFO", 4) == 0) {
          while (left >= 8) {
            unsigned char sid[4]; uint32_t sl;
            if (fread(sid,1,4,ft->fp)!=4) break;
            if (be) rd4b(ft->fp,&sl); else rd4l(ft->fp,&sl);
            if (left < 8 + sl) break;
            if (memcmp(sid, be ? "NCTI" : "ICMT", 4) == 0) {
              unsigned char *buf = malloc(sl+1);
              if (fread(buf,1,sl,ft->fp)!=(size_t)sl) { free(buf); break; }
              buf[sl] = 0;
              if (W->nblk == 0) ft->encoding.comment = xstrdup((char*)buf);
              free(buf);
            } else fseek(ft->fp, sl, SEEK_CUR);
            left -= 8 + sl + (sl & 1);
          }
        } else { fseek(ft->fp, left, SEEK_CUR); left = 0; }
      } else {
        fseek(ft->fp, len + (len & 1), SEEK_CUR);
      }
    }
  }
  ft->signal.channels = W->ch;
  ft->signal.rate = W->rate;
  switch (W->format) {
    case 1: ft->encoding.encoding = (W->bits == 8) ? SOX_ENCODING_UNSIGNED : SOX_ENCODING_SIGNED;
            ft->encoding.precision = W->bits; break;
    case 3: ft->encoding.encoding = SOX_ENCODING_FLOAT;
            ft->encoding.precision = (W->bits == 64) ? 54 : 25; break;
    case 6: ft->encoding.encoding = SOX_ENCODING_ALAW; ft->encoding.precision = 13; break;
    case 7: ft->encoding.encoding = SOX_ENCODING_ULAW; ft->encoding.precision = 14; break;
    case 2: ft->encoding.encoding = SOX_ENCODING_MS_ADPCM; ft->encoding.precision = 14; break;
    case 17: ft->encoding.encoding = SOX_ENCODING_IMA_ADPCM; ft->encoding.precision = 13; break;
    default: sox_fail("%s: unsupported WAVE format %d", ft->filename, W->format); return SOX_EOF;
  }
  if (W->samples) ft->length = W->samples;
  else if (W->datalen && W->format != 2 && W->format != 17)
    ft->length = W->datalen / (W->blk ? W->blk : 1) * (W->blk ? (W->brate ? W->brate / W->rate : 1) : 0);
  return 0;
}
FEOF
