  int newDelta = ((nib & 8) ? -1 : 1) * ((nib & 4) ? ((nib & 3) * scaleFactor) : (0));
  int delta = scaleFactor * ((nib & 4) ? (nib & 3) : (-(nib & 3))) / 4;
