  *predictorDelta = newPredictor;
  *predictor = newPredictor + (scaleFactor * (((nib & 8) ? -(nib & 3) : (nib & 3)))) / 4;
  if (*predictor > 32767) *predictor = 32767;
  else if (*predictor < -32768) *predictor = -32768;
  return *predictor;
