static int ms_encode_nibble(int sample, int *predictor, int *predictorDelta, int *scaleFactor, int coefIdx)
{
  int best = 0, bestErr = 0, i;
  for (i = 0; i < 8; ++i) {
    int c0 = ms_coef[i & 7][0], c1 = ms_coef[i & 7][1];
    int np = (c0 * (*predictor) + c1 * (*predictorDelta)) >> 8;
    int err = sample - np;
    int nib = 0, val;
    if (err < 0) { nib = 8; err = -err; }
    if (err > *scaleFactor) { nib |= 4; err -= *scaleFactor; }
    if (err > *scaleFactor / 2) nib |= 2;
    val = *scaleFactor * (((nib & 8) ? -(nib & 3) : (nib & 3))) / 4;
    err = sample - (np + val);
    if (i == 0 || abs(err) < abs(bestErr)) { best = i; bestErr = err; }
  }
