int wav_startwrite(sox_format_t *ft)
{
  sox_encoding_t e = ft->encoding.encoding;
  unsigned bits = sox_encoding_bits_per_sample(e, ft->encoding.precision);
  ft->priv = calloc(1, sizeof(wav_t));
  memset(W, 0, sizeof(wav_t));
  W->is_be = 0;
  W->ch = ft->signal.channels;
  W->rate = (unsigned)ft->signal.rate;
  switch (e) {
    case SOX_ENCODING_UNSIGNED: case SOX_ENCODING_SIGNED: W->format = 1; break;
    case SOX_ENCODING_FLOAT: W->format = 3; break;
    case SOX_ENCODING_ALAW: W->format = 6; break;
    case SOX_ENCODING_ULAW: W->format = 7; break;
    case SOX_ENCODING_MS_ADPCM: W->format = 2; break;
    case SOX_ENCODING_IMA_ADPCM: W->format = 17; break;
