  else if (W->format == 3) W->blk = W->ch * (bits/8);
  else if (W->format == 6 || W->format == 7) W->blk = W->ch;
  else if (W->format == 2) {
    unsigned bpc = W->rate >= 16000 ? 1024 : 256;
    W->blk = bpc * W->ch;
    W->spb = 2 * (bpc - 6);
    W->brate = W->rate * W->blk / W->spb;
  } else if (W->format == 17) {
    unsigned bpc = W->rate >= 16000 ? 1024 : 256;
    W->blk = bpc * W->ch;
    W->spb = 2 * (bpc - 4) - 1;
    W->brate = W->rate * W->blk / W->spb;
  }
  fwrite(W->is_be ? "RIFX" : "RIFF", 1, 4, ft->fp);
  wr4l(ft->fp, 0);
  fwrite("WAVE", 1, 4, ft->fp);
  wav_write_fmt(ft);
  if (W->format != 1) {
    fwrite("fact", 1, 4, ft->fp); wr4l(ft->fp, 4); wr4l(ft->fp, 0);
    W->fact_written = 1;
  }
