    int c0 = ms_coef[best & 7][0], c1 = ms_coef[best & 7][1];
    int np = (c0 * (*predictor) + c1 * (*predictorDelta)) >> 8;
    int err = sample - np;
    int nib = 0;
    if (err < 0) { nib = 8; err = -err; }
    if (err > *scaleFactor) { nib |= 4; err -= *scaleFactor; }
    if (err > *scaleFactor / 2) nib |= 2;
    *predictor = np + *scaleFactor * (((nib & 8) ? -(nib & 3) : (nib & 3))) / 4;
    if (*predictor > 32767) *predictor = 32767; else if (*predictor < -32768) *predictor = -32768;
    *predictorDelta = np;
    return nib;
  }
}

sox_size_t wav_read(sox_format_t *ft, sox_sample_t *buf, sox_size_t nsamp)
{
  sox_size_t n = 0;
  if (W->format == 2 || W->format == 17) {
    /* block based */
    sox_size_t total = 0;
    while (total < nsamp) {
      sox_size_t avail;
      if (W->blksamps == 0) {
        unsigned blksz = W->blk;
        if (W->datalen && W->dataoff + (W->total/W->spb+1)*blksz > W->dataoff + W->datalen) blksz = W->datalen % W->blk;
        if (blksz == 0) break;
        if (fread(W->block, 1, blksz, ft->fp) != blksz) { ft->eof = 1; break; }
        W->nblk = blksz;
        if (W->format == 2) {
          int c;
          for (c = 0; c < (int)W->ch; ++c) {
            int16_t a = (int16_t)(W->block[c*4] | (W->block[c*4+1] << 8));
            int16_t b = (int16_t)(W->block[c*4+2] | (W->block[c*4+3] << 8));
            W->pred[c] = a; W->predD[c] = b; W->scale[c] = b;
            W->idx[c] = 0;
          }
          W->blkpos = 0;
          W->blksamps = 2 * (blksz / W->ch - 4);
          W->blksamps = W->spb;
        } else {
          int c;
          for (c = 0; c < (int)W->ch; ++c) {
            int16_t a = (int16_t)(W->block[c*4] | (W->block[c*4+1] << 8));
            W->pred[c] = a; W->idx[c] = 0;
          }
          W->blkpos = 0;
          W->blksamps = 2 * (blksz / W->ch - 4);
        }
      }
      avail = W->blksamps - W->blkpos;
      if (avail == 0) break;
      {
        sox_size_t take = nsamp - total < avail ? nsamp - total : avail;
        sox_size_t i;
        for (i = 0; i < take; ++i) {
          int c = (int)(i % W->ch);
          int nib;
          sox_uint64_t pos = W->blkpos + i;
          sox_uint64_t nibpos;
          if (W->format == 2) {
            nibpos = 4 * W->ch + pos / W->ch;
            nib = (pos / W->ch) & 1 ? (W->block[nibpos] >> 4) : (W->block[nibpos] & 0xF);
            buf[total + i] = (sox_sample_t)(ms_decode_nibble(nib, &W->pred[c], &W->predD[c], W->scale[c], nib & 7) << 16);
          } else {
            nibpos = 4 * W->ch + pos / W->ch;
            nib = (pos / W->ch) & 1 ? (W->block[nibpos] >> 4) : (W->block[nibpos] & 0xF);
            buf[total + i] = (sox_sample_t)(sox_ima_decode_nibble(nib, &W->idx[c], &W->pred[c]) << 16);
          }
        }
        W->blkpos += take;
        total += take;
        if (W->blkpos >= W->blksamps) { W->blksamps = 0; W->total += W->blksamps ? 0 : 0; W->total += 0; }
        n += take;
      }
    }
    return n;
  }
  return raw_read_samples(ft, buf, nsamp);
}

