  wr4l(ft->fp, 0);
  fwrite("WAVE", 1, 4, ft->fp);
  wav_write_fmt(ft);
  if (W->format != 1) {
    fwrite("fact", 1, 4, ft->fp); wr4l(ft->fp, 4); wr4l(ft->fp, 0);
    W->fact_written = 1;
  }
  fwrite("data", 1, 4, ft->fp);
  W->dataoff = ftell(ft->fp);
  wr4l(ft->fp, 0);
  return 0;
}

static void wav_patch(sox_format_t *ft)
{
  long end = ftell(ft->fp);
  uint32_t riff = (uint32_t)(end - 8);
  fseek(ft->fp, 4, SEEK_SET);
  W->is_be ? wr4b(ft->fp, riff) : wr4l(ft->fp, riff);
  fseek(ft->fp, W->dataoff, SEEK_SET);
  W->is_be ? wr4b(ft->fp, (uint32_t)W->datalen) : wr4l(ft->fp, (uint32_t)W->datalen);
  fseek(ft->fp, end, SEEK_SET);
}

sox_size_t wav_write(sox_format_t *ft, const sox_sample_t *buf, sox_size_t nsamp)
{
  sox_size_t n;
  if (W->format == 2 || W->format == 17) {
    /* buffer samples into blocks */
    sox_size_t total = 0;
    while (total < nsamp) {
      sox_size_t avail = W->spb - W->blkpos;
      sox_size_t take = nsamp - total < avail ? nsamp - total : avail;
      sox_size_t i;
      if (W->blkpos == 0) {
        int c;
        for (c = 0; c < (int)W->ch; ++c) {
          W->pred[c] = (int)(buf[total + c] >> 16);
          W->predD[c] = 0; W->scale[c] = 1;
          W->idx[c] = 0;
        }
      }
      for (i = 0; i < take; ++i) {
        int c = (int)(i % W->ch);
        int nib;
        sox_size_t pos = W->blkpos + i;
        sox_size_t nibpos = 4 * W->ch + pos / W->ch;
        int s = (int)(buf[total + i] >> 16);
        if (W->format == 2) nib = ms_encode_nibble(s, &W->pred[c], &W->predD[c], &W->scale[c], 0);
        else nib = sox_ima_encode_nibble(s, &W->idx[c], &W->pred[c]);
        if (pos & 1) W->outblk[nibpos] |= (nib << 4);
        else W->outblk[nibpos] = nib;
      }
      W->blkpos += take;
      total += take;
      if (W->blkpos >= W->spb) {
        int c;
        unsigned char *hdr = W->outblk;
        for (c = 0; c < (int)W->ch; ++c) {
          hdr[c*4] = W->pred[c] & 0xff; hdr[c*4+1] = (W->pred[c] >> 8) & 0xff;
          if (W->format == 2) {
            hdr[c*4+2] = W->predD[c] & 0xff; hdr[c*4+3] = (W->predD[c] >> 8) & 0xff;
          } else { hdr[c*4+2] = 0; hdr[c*4+3] = 0; }
        }
        fwrite(W->outblk, 1, W->blk, ft->fp);
        W->written_blocks++;
        W->datalen += W->blk;
        W->blkpos = 0;
        memset(W->outblk, 0, sizeof(W->outblk));
      }
    }
    n = total;
  } else {
    n = raw_write_samples(ft, buf, nsamp);
  }
  W->datalen += 0;
  ft->olength += n;
  return n;
}

int wav_stopwrite(sox_format_t *ft)
{
  if (W->format == 2 || W->format == 17 && W->blkpos) {
    int c;
    unsigned char *hdr = W->outblk;
    for (c = 0; c < (int)W->ch; ++c) {
