/* ---- SoX native ---- */
typedef struct { sox_uint64_t dataoff; unsigned cmtlen; } sn_t;

static int sox_startread(sox_format_t *ft)
{
  unsigned char id[4];
  if (fread(id,1,4,ft->fp)!=4) return SOX_EOF;
  if (memcmp(id,".SoX",4)!=0) return SOX_EOF;
  { int ver = fgetc(ft->fp);
    unsigned cl;
    double rate;
    uint32_t ch;
    unsigned char dr[8];
    if (ver == EOF) return SOX_EOF;
    fseek(ft->fp, 3, SEEK_CUR);
    if (fread(dr,1,8,ft->fp)!=8) return SOX_EOF;
    ft->signal.channels = dr[0] | (dr[1]<<8) | (dr[2]<<16) | ((uint32_t)dr[3]<<24);
    (void)ch;
    if (fread(dr,1,8,ft->fp)!=8) return SOX_EOF;
    rate = 0;
    { int i; unsigned char b[8]; memcpy(b,dr,8);
      for (i = 0; i < 4; ++i) { unsigned char t = b[i]; b[i] = b[7-i]; b[7-i] = t; }
      memcpy(&rate, b, 8); }
    ft->signal.rate = rate;
    ft->encoding.encoding = SOX_ENCODING_SIGNED;
    ft->encoding.precision = 32;
    ft->encoding.opposite_endian = 0;
    if (fread(dr,1,4,ft->fp)!=4) return SOX_EOF;
    cl = dr[0] | (dr[1]<<8) | (dr[2]<<16) | ((uint32_t)dr[3]<<24);
    if (cl) {
      unsigned char *c = malloc(cl+1);
      if (fread(c,1,cl,ft->fp)!=(size_t)cl) { free(c); return SOX_EOF; }
      c[cl] = 0;
      ft->encoding.comment = xstrdup((char*)c);
      free(c);
      fseek(ft->fp, (long)((cl + 7) & ~7u) - cl, SEEK_CUR);
    }
    ((sn_t*)ft->priv = calloc(1,sizeof(sn_t)))->dataoff = ftell(ft->fp);
    ft->length = 0;
    { /* length is at offset 8 */
      long cur = ftell(ft->fp);
      fseek(ft->fp, 8, SEEK_SET);
      if (fread(dr,1,4,ft->fp)==4) ft->length = dr[0]|(dr[1]<<8)|(dr[2]<<16)|((uint32_t)dr[3]<<24);
      fseek(ft->fp, cur, SEEK_SET);
    }
  }
  return 0;
}

sox_size_t sox_read(sox_format_t *ft, sox_sample_t *buf, sox_size_t nsamp)
{ return raw_read_samples(ft, buf, nsamp); }

int sox_startwrite(sox_format_t *ft)
{
  unsigned cl = 0, pad;
  ft->priv = calloc(1,sizeof(sn_t));
  ft->encoding.encoding = SOX_ENCODING_SIGNED;
  ft->encoding.precision = 32;
  if (ft->encoding.comment) cl = (unsigned)strlen(ft->encoding.comment);
  pad = (cl + 7) & ~7u;
  fwrite(".SoX",1,4,ft->fp);
  fputc(28 + (int)pad, ft->fp);
  fputc(0,ft->fp); fputc(0,ft->fp); fputc(0,ft->fp);
  wr4l(ft->fp, 0);      /* length */
  wr4l(ft->fp, 0);
  { double r = ft->signal.rate; unsigned char b[8]; int i;
    memcpy(b,&r,8);
    for (i = 0; i < 4; ++i) { unsigned char t = b[i]; b[i] = b[7-i]; b[7-i] = t; }
    fwrite(b,1,8,ft->fp); }
  wr4l(ft->fp, ft->signal.channels);
  wr4l(ft->fp, cl);
  if (cl) { fwrite(ft->encoding.comment,1,cl,ft->fp); { unsigned i; for (i = cl; i < pad; ++i) fputc(0,ft->fp); } }
  ((sn_t*)ft->priv)->dataoff = ftell(ft->fp);
  ((sn_t*)ft->priv)->cmtlen = cl;
  return 0;
}

sox_size_t sox_write(sox_format_t *ft, const sox_sample_t *buf, sox_size_t nsamp)
{ return raw_write_samples(ft, buf, nsamp); }

int sox_stopwrite(sox_format_t *ft)
{
  long end = ftell(ft->fp);
  uint32_t len = (uint32_t)(ft->olength / (ft->signal.channels ? ft->signal.channels : 1));
  fseek(ft->fp, 8, SEEK_SET);
  wr4l(ft->fp, len);
  fseek(ft->fp, end, SEEK_SET);
  return 0;
}

/* ---- NIST SPH ---- */
static int sph_startread(sox_format_t *ft)
{
  unsigned char buf[1024];
  char *p, *line;
  if (fread(buf,1,1024,ft->fp)!=1024) return SOX_EOF;
  if (memcmp(buf,"NIST_1A",7)!=0) return SOX_EOF;
