  ft->signal.rate = 0;
  p = (char*)buf;
  while (*p) {
    char *e = strchr(p,'\n');
    if (!e) break;
    *e = 0;
    line = p;
    if (!strncmp(line,"sample_n_bytes -i ",18)) ft->encoding.precision = atoi(line+18);
    else if (!strncmp(line,"channel_count -i ",17)) ft->signal.channels = atoi(line+17);
    else if (!strncmp(line,"sample_rate -i ",15)) ft->signal.rate = atoi(line+15);
    else if (!strncmp(line,"sample_byte_format -s2 ",23)) {
      ft->encoding.opposite_endian = (line[23] == '1') ? 0 : 1;
      if (line[23] == '0') ft->encoding.opposite_endian = 1;
    }
    else if (!strncmp(line,"sample_coding -s",16)) {
      char const *v = line+18;
      while (*v == ' ') ++v;
      if (!strncaseeq(v,"pcm",3)) ft->encoding.encoding = SOX_ENCODING_SIGNED;
      else if (!strncaseeq(v,"ulaw",4)) { ft->encoding.encoding = SOX_ENCODING_ULAW; ft->encoding.precision = 14; }
      else ft->encoding.encoding = SOX_ENCODING_SIGNED;
    }
    else if (!strncmp(line,"sample_count -i ",16)) ft->length = strtoul(line+16,NULL,10);
    else if (!strncmp(line,"utterance_id -s",15)) {
      char const *v = line+17; while (*v==' ') ++v;
      ft->encoding.comment = xstrdup(v);
    }
    p = e + 1;
  }
  if (ft->encoding.encoding == SOX_ENCODING_SIGNED && (ft->encoding.precision == 0 || ft->signal.rate == 0)) {
    sox_fail("%s: Error reading Sphere header", ft->filename);
    return SOX_EOF;
  }
  return 0;
}

sox_size_t sph_read(sox_format_t *ft, sox_sample_t *buf, sox_size_t nsamp)
{ return raw_read_samples(ft, buf, nsamp); }

int sph_startwrite(sox_format_t *ft)
{
  unsigned bps = sox_encoding_bits_per_sample(ft->encoding.encoding, ft->encoding.precision);
  char hdr[1024];
  int n = 0;
  const char *bo;
  const char *coding = "pcm";
  ft->encoding.encoding = SOX_ENCODING_SIGNED;
  ft->encoding.precision = ft->encoding.precision ? ft->encoding.precision : 16;
  bps = ft->encoding.precision;
  bo = ft->encoding.opposite_endian ? "01" : "10";
  n += sprintf(hdr+n, "NIST_1A\n");
  n += sprintf(hdr+n, "   1024\n");
  n += sprintf(hdr+n, "sample_n_bytes -i %u\n", bps/8);
  n += sprintf(hdr+n, "channel_count -i %u\n", ft->signal.channels);
  n += sprintf(hdr+n, "sample_byte_format -s2 %s\n", bo);
  n += sprintf(hdr+n, "sample_rate -i %u\n", (unsigned)ft->signal.rate);
  n += sprintf(hdr+n, "sample_coding -s3 %s\n", coding);
  n += sprintf(hdr+n, "end_head\n");
  memset(hdr+n, 0, 1024-n);
  fwrite(hdr,1,1024,ft->fp);
  ft->encoding.opposite_endian = 0;
  return 0;
}

sox_size_t sph_write(sox_format_t *ft, const sox_sample_t *buf, sox_size_t nsamp)
{ return raw_write_samples(ft, buf, nsamp); }

/* ---- dat ---- */
static int dat_startread(sox_format_t *ft)
{
  char line[512];
  int rate = 0, ch = 0;
  long dataoff = 0;
  while (fgets(line, sizeof(line), ft->fp)) {
    dataoff = ftell(ft->fp);
    if (line[0] == ';') {
      if (!strncmp(line,"; Sample Rate",13)) rate = atoi(line+13);
      else if (!strncmp(line,"; Channels",10)) ch = atoi(line+10);
      continue;
    }
    if (sscanf(line,"%lf %lf", &rate, &ch) == 2 || 1) break;
  }
  (void)ch;
  ft->signal.rate = rate;
  ft->signal.channels = 1;
  ft->encoding.encoding = SOX_ENCODING_FLOAT_TEXT;
  ft->encoding.precision = 54;
  ft->signal.length = 0;
  fseek(ft->fp, dataoff, SEEK_SET);
  return 0;
}

static sox_size_t dat_read(sox_format_t *ft, sox_sample_t *buf, sox_size_t nsamp)
{
  sox_size_t n = 0;
  double t, v;
  while (n < nsamp) {
    int c;
    if ((c = fgetc(ft->fp)) == EOF) { ft->eof = 1; break; }
    ungetc(c, ft->fp);
    if (fscanf(ft->fp, "%lf %lf", &t, &v) != 2) { ft->eof = 1; break; }
    { int ch; while ((ch = fgetc(ft->fp)) != '\n' && ch != EOF) ; }
    buf[n++] = (sox_sample_t)(v * 2147483648.0);
  }
  return n;
}

static sox_size_t dat_write(sox_format_t *ft, const sox_sample_t *buf, sox_size_t nsamp)
{
  sox_size_t i, n = 0;
  double rate = ft->signal.rate;
  for (i = 0; i < nsamp; i += ft->signal.channels) {
    unsigned c;
    for (c = 0; c < ft->signal.channels; ++c) {
      double t = (double)((ft->olength + i) / ft->signal.channels) / rate;
      double v = (double)buf[i+c] / 2147483648.0;
      fprintf(ft->fp, "%16.7e %16.12g \r\n", t, v);
    }
    n += ft->signal.channels;
  }
  return n;
}

int dat_startwrite(sox_format_t *ft)
{
  ft->encoding.encoding = SOX_ENCODING_FLOAT_TEXT;
  ft->encoding.precision = 54;
  fprintf(ft->fp, "; Sample Rate %u\r\n", (unsigned)ft->signal.rate);
  fprintf(ft->fp, "; Channels %u\r\n", ft->signal.channels);
  return 0;
}

int dat_stopwrite(sox_format_t *ft) { (void)ft; return 0; }
int dat_stopread(sox_format_t *ft) { (void)ft; return 0; }
FEOF
echo ok"}

