/* ---- 8SVX ---- */
typedef struct { long bodyoff; sox_uint64_t bytes; } sx_t;

static int s8_startread(sox_format_t *ft)
{
  unsigned char id[4]; uint32_t len;
  if (fread(id,1,4,ft->fp)!=4||memcmp(id,"FORM",4)!=0) return SOX_EOF;
  if (rd4b(ft->fp,&len)) return SOX_EOF;
  if (fread(id,1,4,ft->fp)!=4||memcmp(id,"8SVX",4)!=0) return SOX_EOF;
  ft->priv = calloc(1,sizeof(sx_t));
  ft->encoding.encoding = SOX_ENCODING_SIGNED;
  ft->encoding.precision = 8;
  for (;;) {
    if (fread(id,1,4,ft->fp)!=4) return SOX_EOF;
    if (rd4b(ft->fp,&len)) return SOX_EOF;
    if (memcmp(id,"VHDR",4)==0) {
      uint32_t a; uint32_t rate; unsigned char b[2]; uint32_t vol;
      if (rd4b(ft->fp,&a)) return SOX_EOF;
      ft->length = a;
      fseek(ft->fp, 8, SEEK_CUR);
      if (rd2b(ft->fp,&rate)) return SOX_EOF;
      ft->signal.rate = rate;
      fseek(ft->fp, 6, SEEK_CUR);
      len -= 20;
      if (len & 1) fgetc(ft->fp);
    } else if (memcmp(id,"CHAN",4)==0) {
      uint32_t v; if (rd4b(ft->fp,&v)) return SOX_EOF;
      switch (v) { case 0: ft->signal.channels = 2; break; case 2: ft->signal.channels = 1; break;
                   case 4: case 6: ft->signal.channels = 4; break; default: ft->signal.channels = v; }
    } else if (memcmp(id,"ANNO",4)==0) {
      unsigned char *buf = malloc(len+1);
      if (fread(buf,1,len,ft->fp)!=(size_t)len) { free(buf); return SOX_EOF; }
      buf[len]=0; if (!ft->encoding.comment) ft->encoding.comment = xstrdup((char*)buf);
      free(buf); if (len & 1) fgetc(ft->fp);
    } else if (memcmp(id,"BODY",4)==0) {
      ((sx_t*)ft->priv)->bodyoff = ftell(ft->fp);
      break;
    } else { fseek(ft->fp, len + (len&1), SEEK_CUR); }
  }
  return 0;
}

