  fwrite("FORM",1,4,ft->fp); wr4b(ft->fp,0);
  fwrite("8SVX",1,4,ft->fp);
  fwrite("VHDR",1,4,ft->fp); wr4b(ft->fp,20);
  wr4b(ft->fp,0); wr4b(ft->fp,0); wr4b(ft->fp,0);
