/* resolve a long option name; returns the index or -1 */
static int longopt_index(char const *name, int *ambig, int *nambig)
{
  int i, n = 0, len = (int)strlen(name), found = -1;
  for (i = 0; opts[i].name; ++i) {
    if (strncaseeq(opts[i].name, name, (size_t)len)) {
      ++n;
      if (n == 1) found = i;
      else if (*nambig < 8) ambig[(*nambig)++] = i;
    }
  }
  *nambig = n;
  return n == 1 ? found : -1;
}

