  for (i = 0; i < argc; ++i) {
    char const *a = argv[i];
    if (a[0] == '-' && a[1] && !isdigit((unsigned char)a[1])) {
      switch (a[1]) {
        case 'e': p->equalise = 1; break;
        case 'B': p->balance = 1; break;
        case 'b': p->balance = 1; p->balance_clip = 1; break;
        case 'r': p->reclaim = 1; break;
        case 'n': p->norm = 1; break;
        case 'l': p->limiter = 1; break;
        case 'h': p->reclaim = 2; break;
        default: sox_fail("Usage: gain [-e|-B|-b|-r] [-n] [-l|-h] [gain-dB]"); return SOX_EOF;
