}

static void gain_reset(gain_t *p, unsigned ch)
{
  if (p->peaks) free(p->peaks);
  if (p->rms) free(p->rms);
  p->peaks = calloc(ch, sizeof(double));
  p->rms = calloc(ch, sizeof(double));
  p->count = 0;
}

static double gain_compute(gain_t *p, unsigned ch)
{
  unsigned i;
  double factor = pow(10.0, p->gain / 20.0);
  if (p->norm) {
    double max = 0;
    for (i = 0; i < ch; ++i) if (p->peaks[i] > max) max = p->peaks[i];
    if (max > 0) factor = SOX_SAMPLE_MAX / max * factor;
  } else if (p->equalise) {
    double max = 0;
    for (i = 0; i < ch; ++i) if (p->peaks[i] > max) max = p->peaks[i];
    for (i = 0; i < ch; ++i) if (p->peaks[i] > 0) factor = SOX_SAMPLE_MAX / p->peaks[i];
  } else if (p->balance) {
    double maxr = 0;
    for (i = 0; i < ch; ++i) if (p->rms[i] > maxr) maxr = p->rms[i];
    for (i = 0; i < ch; ++i) if (p->rms[i] > 0) factor = maxr / p->rms[i] * pow(10.0, p->gain/20.0);
  }
  return factor;
}

static int gain_start(sox_effect_t *e)
{
  gain_t *p = e->priv;
  e->out_signal = e->in_signal;
  e->extra = p->gain != 0 ? fabs(p->gain)/6.02 : 0;
  gain_reset(p, e->in_signal.channels ? e->in_signal.channels : 1);
  p->buffering = (p->norm || p->equalise || p->balance);
  if (p->buffering) { p->bufcap = 1 << 20; p->buffer = malloc(p->bufcap * sizeof(sox_sample_t)); p->buflen = 0; }
  return SOX_SUCCESS;
}

static int gain_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{
