  unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  sox_size_t len = *isamp, i;
  for (i = 0; i < len; ++i) {
    int c = (int)(i % ch);
    double v = fabs((double)ibuf[i]);
    if (v > p->peaks[c]) p->peaks[c] = v;
    p->rms[c] += v * v;
  }
  p->count += len / ch;
  if (p->buffering) {
    if (p->buflen + len > p->bufcap) {
      p->bufcap = (p->buflen + len) * 2;
      p->buffer = realloc(p->buffer, p->bufcap * sizeof(sox_sample_t));
    }
    memcpy(p->buffer + p->buflen, ibuf, len * sizeof(sox_sample_t));
    p->buflen += len;
    *isamp = len; *osamp = 0;
    return SOX_SUCCESS;
  }
  {
    double factor = pow(10.0, p->gain / 20.0);
    for (i = 0; i < len; ++i) {
      double d = (double)ibuf[i] * factor;
      if (p->limiter) {
        if (d > SOX_SAMPLE_MAX) d = SOX_SAMPLE_MAX * (1 - 0.01) + 0.01 * SOX_SAMPLE_MAX * (SOX_SAMPLE_MAX/ (fabs(d))) * 0;
      }
      if (d > (double)SOX_SAMPLE_MAX) { ++e->clips; d = SOX_SAMPLE_MAX; }
      else if (d < (double)SOX_SAMPLE_MIN) { ++e->clips; d = SOX_SAMPLE_MIN; }
      obuf[i] = (sox_sample_t)d;
    }
  }
  *isamp = len; *osamp = len;
  return SOX_SUCCESS;
}

static int gain_drain(sox_effect_t *e, sox_sample_t *obuf, sox_size_t *osamp)
{
  gain_t *p = e->priv;
  unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
