  return SOX_SUCCESS;
}

/* ---------------- channels / remix ---------------- */
typedef struct { unsigned ochannels; double **matrix; } chan_t;

static int chan_getopts(sox_effect_t *e, char **argv, int argc)
{
  chan_t *p = calloc(1, sizeof(chan_t));
  unsigned n;
  e->priv = p;
  if (argc != 1) { sox_fail("Usage: channels number"); return SOX_EOF; }
  n = (unsigned)atoi(argv[0]);
  if (n < 1 || n > 8) { sox_fail("channels: invalid number of channels `%s'", argv[0]); return SOX_EOF; }
  p->ochannels = n;
  return SOX_SUCCESS;
}

static int chan_start(sox_effect_t *e)
{
  chan_t *p = e->priv;
  unsigned i, j;
  unsigned ich = e->in_signal.channels ? e->in_signal.channels : 1;
  p->matrix = malloc(p->ochannels * sizeof(double*));
  for (i = 0; i < p->ochannels; ++i) {
    p->matrix[i] = calloc(ich, sizeof(double));
    if (i < ich) p->matrix[i][i] = 1;
    else if (ich > 0) p->matrix[i][i % ich] = 1;
  }
  e->out_signal = e->in_signal;
  e->out_signal.channels = p->ochannels;
  return SOX_SUCCESS;
}

static int chan_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{
  chan_t *p = e->priv;
  unsigned ich = e->in_signal.channels ? e->in_signal.channels : 1;
  sox_size_t max = *isamp / ich;
  if (*osamp / p->ochannels < max) max = *osamp / p->ochannels;
  sox_size_t i, o;
  for (i = 0; i < max; ++i)
    for (o = 0; o < p->ochannels; ++o) {
      double d = 0; unsigned k;
      for (k = 0; k < ich; ++k) d += (double)ibuf[i*ich + k] * p->matrix[o][k];
      if (d > (double)SOX_SAMPLE_MAX) { ++e->clips; d = SOX_SAMPLE_MAX; }
      else if (d < (double)SOX_SAMPLE_MIN) { ++e->clips; d = SOX_SAMPLE_MIN; }
      obuf[i*p->ochannels + o] = (sox_sample_t)d;
    }
  *isamp = max * ich; *osamp = max * p->ochannels;
  return SOX_SUCCESS;
}

/* ---------------- reverse ---------------- */
typedef struct { sox_sample_t *buf; sox_size_t len, cap; } rev_t;

static int rev_start(sox_effect_t *e)
{
  rev_t *p = calloc(1, sizeof(rev_t));
  e->priv = p;
  e->out_signal = e->in_signal;
  p->cap = 1 << 20;
  p->buf = malloc(p->cap * sizeof(sox_sample_t));
  return SOX_SUCCESS;
}

static int rev_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{
  rev_t *p = e->priv;
  sox_size_t len = *isamp;
  (void)obuf; (void)osamp;
  if (p->len + len > p->cap) { p->cap = (p->len + len) * 2; p->buf = realloc(p->buf, p->cap * sizeof(sox_sample_t)); }
  memcpy(p->buf + p->len, ibuf, len * sizeof(sox_sample_t));
  p->len += len;
  *isamp = len; *osamp = 0;
  return SOX_SUCCESS;
}

static int rev_drain(sox_effect_t *e, sox_sample_t *obuf, sox_size_t *osamp)
{
  rev_t *p = e->priv;
  sox_size_t i, n = p->len;
  for (i = 0; i < n; ++i) obuf[i] = p->buf[n - 1 - i];
  *osamp = n < *osamp ? n : *osamp;
  return SOX_SUCCESS;
}
