/* ---------------- vol ---------------- */
typedef struct { double gain; int type; double limiter; int limiter_given; } vol_t;

static int vol_getopts(sox_effect_t *e, char **argv, int argc)
{
  vol_t *p = calloc(1, sizeof(vol_t));
  e->priv = p;
  if (argc < 1 || argc > 3) { sox_fail("Usage: vol GAIN [TYPE [LIMITERGAIN]]"); return SOX_EOF; }
  p->type = 0;
  if (argc >= 2) {
    if (strcaseeq(argv[1], "amplitude")) p->type = 0;
    else if (strcaseeq(argv[1], "power")) p->type = 1;
    else if (strcaseeq(argv[1], "dB")) p->type = 2;
    else { sox_fail("Usage: vol GAIN [TYPE [LIMITERGAIN]]"); return SOX_EOF; }
  }
  p->gain = dbl(argv[0], 1);
  if (p->type == 1) p->gain = sqrt(fabs(p->gain)) * (p->gain < 0 ? -1 : 1);
  else if (p->type == 2) p->gain = pow(10.0, p->gain / 20.0);
  if (argc >= 3) { p->limiter = dbl(argv[2], 0); p->limiter_given = 1; }
  return SOX_SUCCESS;
}

static int vol_start(sox_effect_t *e)
{
  vol_t *p = e->priv;
  e->out_signal = e->in_signal;
  e->extra = 0;
  if (p->gain != 1) {
    double g = p->gain;
    double l = log2(fabs(g));
    if (l > 0) e->extra = l;
    else e->extra = 0;
  }
  if (p->type == 2 && p->gain == 1) e->extra = 0;
  return SOX_SUCCESS;
}

static int vol_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{
