      double lim = p->limiter;
      if (d > SOX_SAMPLE_MAX * lim) d = SOX_SAMPLE_MAX - (SOX_SAMPLE_MAX - SOX_SAMPLE_MAX*lim) * (lim / (d/SOX_SAMPLE_MAX));
      else if (d < SOX_SAMPLE_MIN * lim) d = SOX_SAMPLE_MIN - (SOX_SAMPLE_MIN - SOX_SAMPLE_MIN*lim) * (lim / (d/SOX_SAMPLE_MIN));
    }
    if (d > (double)SOX_SAMPLE_MAX) { ++e->clips; d = SOX_SAMPLE_MAX; }
    else if (d < (double)SOX_SAMPLE_MIN) { ++e->clips; d = SOX_SAMPLE_MIN; }
    obuf[i] = (sox_sample_t)d;
  }
