/* ---------------- gain / norm ---------------- */
typedef struct {
  double gain;      /* dB */
  int balance, balance_clip, norm, equalise, reclaim, limiter;
  sox_size_t count;
  double *peaks, *rms;
  int buf;
  sox_sample_t *buffer;
  sox_size_t buflen, bufcap;
  int buffering;
} gain_t;

static int gain_getopts(sox_effect_t *e, char **argv, int argc)
{
  gain_t *p = calloc(1, sizeof(gain_t));
  int i;
  e->priv = p;
  p->gain = 0;
  for (i = 0; i < argc; ++i) {
    char const *a = argv[i];
    if (a[0] == '-' && a[1] && !isdigit((unsigned char)a[1])) {
      switch (a[1]) {
        case 'e': p->equalise = 1; break;
        case 'B': p->balance = 1; break;
        case 'b': p->balance = 1; p->balance_clip = 1; break;
        case 'r': p->reclaim = 1; break;
        case 'n': p->norm = 1; break;
        case 'l': p->limiter = 1; break;
        case 'h': p->reclaim = 2; break;
        default: sox_fail("Usage: gain [-e|-B|-b|-r] [-n] [-l|-h] [gain-dB]"); return SOX_EOF;
      }
    } else {
      p->gain = dbl(a, 0);
    }
  }
  return SOX_SUCCESS;
}

static void gain_reset(gain_t *p, unsigned ch)
{
  if (p->peaks) free(p->peaks);
  if (p->rms) free(p->rms);
  p->peaks = calloc(ch, sizeof(double));
  p->rms = calloc(ch, sizeof(double));
  p->count = 0;
}

static double gain_compute(gain_t *p, unsigned ch)
{
  unsigned i;
  double factor = pow(10.0, p->gain / 20.0);
  if (p->norm) {
    double max = 0;
    for (i = 0; i < ch; ++i) if (p->peaks[i] > max) max = p->peaks[i];
    if (max > 0) factor = SOX_SAMPLE_MAX / max * factor;
  } else if (p->equalise) {
    double max = 0;
    for (i = 0; i < ch; ++i) if (p->peaks[i] > max) max = p->peaks[i];
    for (i = 0; i < ch; ++i) if (p->peaks[i] > 0) factor = SOX_SAMPLE_MAX / p->peaks[i];
  } else if (p->balance) {
    double maxr = 0;
    for (i = 0; i < ch; ++i) if (p->rms[i] > maxr) maxr = p->rms[i];
    for (i = 0; i < ch; ++i) if (p->rms[i] > 0) factor = maxr / p->rms[i] * pow(10.0, p->gain/20.0);
  }
  return factor;
}

static int gain_start(sox_effect_t *e)
{
  gain_t *p = e->priv;
  e->out_signal = e->in_signal;
  e->extra = p->gain != 0 ? fabs(p->gain)/6.02 : 0;
  gain_reset(p, e->in_signal.channels ? e->in_signal.channels : 1);
  p->buffering = (p->norm || p->equalise || p->balance);
  if (p->buffering) { p->bufcap = 1 << 20; p->buffer = malloc(p->bufcap * sizeof(sox_sample_t)); p->buflen = 0; }
  return SOX_SUCCESS;
}

static int gain_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{
  gain_t *p = e->priv;
  unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  sox_size_t len = *isamp, i;
  for (i = 0; i < len; ++i) {
    int c = (int)(i % ch);
    double v = fabs((double)ibuf[i]);
    if (v > p->peaks[c]) p->peaks[c] = v;
    p->rms[c] += v * v;
  }
  p->count += len / ch;
  if (p->buffering) {
    if (p->buflen + len > p->bufcap) {
      p->bufcap = (p->buflen + len) * 2;
      p->buffer = realloc(p->buffer, p->bufcap * sizeof(sox_sample_t));
    }
    memcpy(p->buffer + p->buflen, ibuf, len * sizeof(sox_sample_t));
    p->buflen += len;
    *isamp = len; *osamp = 0;
    return SOX_SUCCESS;
  }
  {
    double factor = pow(10.0, p->gain / 20.0);
    for (i = 0; i < len; ++i) {
      double d = (double)ibuf[i] * factor;
      if (p->limiter) {
        if (d > SOX_SAMPLE_MAX) d = SOX_SAMPLE_MAX * (1 - 0.01) + 0.01 * SOX_SAMPLE_MAX * (SOX_SAMPLE_MAX/ (fabs(d))) * 0;
      }
