      else if (d < (double)SOX_SAMPLE_MIN) { ++e->clips; d = SOX_SAMPLE_MIN; }
      obuf[i] = (sox_sample_t)d;
    }
  }
  *isamp = len; *osamp = len;
  return SOX_SUCCESS;
}

static int gain_drain(sox_effect_t *e, sox_sample_t *obuf, sox_size_t *osamp)
{
  gain_t *p = e->priv;
  unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  sox_size_t i;
  double factor = gain_compute(p, ch);
  if (!p->buffering) { *osamp = 0; return SOX_SUCCESS; }
  for (i = 0; i < p->buflen; ++i) {
    double d = (double)p->buffer[i] * factor;
    if (d > (double)SOX_SAMPLE_MAX) { ++e->clips; d = SOX_SAMPLE_MAX; }
    else if (d < (double)SOX_SAMPLE_MIN) { ++e->clips; d = SOX_SAMPLE_MIN; }
    obuf[i] = (sox_sample_t)d;
  }
  if (p->buflen > *osamp) { memcpy(obuf, p->buffer, *osamp * sizeof(sox_sample_t)); }
  else *osamp = p->buflen;
  *osamp = p->buflen < *osamp ? p->buflen : *osamp;
  return SOX_SUCCESS;
}

static int gain_stop(sox_effect_t *e)
{
  gain_t *p = e->priv;
  (void)e;
  if (p->peaks) free(p->peaks);
  if (p->rms) free(p->rms);
  return SOX_SUCCESS;
}

