{"command": "cat >> /workspace/src/effects.c <<'EEOF'

/* ---------------- time parsing ---------------- */
static sox_uint64_t parse_pos(char const *s, sox_rate_t rate, double *outd)
{
  /* [[h:]m:]s[.frac] | samples s | samples */
  double d = 0;
  char *end = NULL;
  if (strchr(s, ':') || strchr(s, '.')) {
    /* time spec */
    double acc = 0;
    char *copy = xstrdup(s), *p = copy;
    double mults[3] = {3600, 60, 1};
    int part = 0;
    char *tok = p;
    /* handle h:m:s */
    while (*p) {
      if (*p == ':') { *p = 0; acc += strtod(tok, NULL) * (part < 3 ? mults[part] : 1); ++part; tok = p+1; }
      ++p;
    }
    acc += strtod(tok, NULL) * (part < 3 ? mults[part] : 1);
    d = acc;
    free(copy);
  } else if (s[strlen(s)-1] == 's') {
    d = strtod(s, &end);
  } else {
    d = strtod(s, &end);
    if (end && *end == '\0') d = d / rate;
  }
  if (outd) *outd = d;
  return (sox_uint64_t)(d * rate + 0.5);
}

/* ---------------- trim ---------------- */
typedef struct { struct { double start; double length; } *pos; int npos; sox_uint64_t offset; int cur; sox_uint64_t skipped; sox_uint64_t taken; sox_uint64_t length; } trim_t;

static int trim_getopts(sox_effect_t *e, char **argv, int argc)
{
  trim_t *p = calloc(1, sizeof(trim_t));
  int i;
  e->priv = p;
  if (argc < 1) { sox_fail("Usage: trim {position}"); return SOX_EOF; }
  p->pos = calloc(argc, sizeof(*p->pos));
  for (i = 0; i < argc; ++i) {
    char const *a = argv[i];
    if (a[0] == '=') { p->pos[i].start = -1; p->pos[i].length = parse_pos(a+1, 1, NULL); }
    else if (a[0] == '-') { p->pos[i].start = -2; p->pos[i].length = parse_pos(a+1, 1, NULL); }
    else { p->pos[i].start = parse_pos(a, 1, NULL); p->pos[i].length = -1; }
  }
  p->npos = argc;
  return SOX_SUCCESS;
}

static int trim_start(sox_effect_t *e)
{
  trim_t *p = e->priv;
  e->out_signal = e->in_signal;
  p->cur = 0;
  p->offset = 0;
  p->skipped = 0;
  p->taken = 0;
  return SOX_SUCCESS;
}

static int trim_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{
  trim_t *p = e->priv;
  sox_rate_t rate = e->in_signal.rate;
  unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  sox_size_t i = 0, o = 0;
  while (i < *isamp) {
    sox_uint64_t frame = (i / ch) + p->skipped;
    if (p->cur >= p->npos) break;
    {
      double start = p->pos[p->cur].start;
      double length = p->pos[p->cur].length;
      sox_uint64_t startpos;
      sox_uint64_t lenpos;
      if (start < 0) startpos = start == -2 ? (sox_uint64_t)(e->in_signal.length * rate) : 0;
      else startpos = (sox_uint64_t)(start * rate + 0.5);
      lenpos = length < 0 ? (sox_uint64_t)-1 : (sox_uint64_t)(length * rate + 0.5);
      if (frame < startpos) { sox_size_t skip = (sox_size_t)((startpos - frame) * ch); if (skip > *isamp - i) skip = *isamp - i; i += skip; p->skipped += skip / ch; continue; }
      if (lenpos != (sox_uint64_t)-1 && frame >= startpos + lenpos) { ++p->cur; p->skipped += i / ch; i = 0; continue; }
      {
        sox_size_t take = *isamp - i;
        if (lenpos != (sox_uint64_t)-1 && frame + take/ch > startpos + lenpos) take = (sox_size_t)((startpos + lenpos - frame) * ch);
        memcpy(obuf + o, ibuf + i, take * sizeof(sox_sample_t));
        o += take; i += take; p->taken += take / ch;
        if (lenpos != (sox_uint64_t)-1 && p->taken >= lenpos) { ++p->cur; p->skipped += i / ch; i = 0; }
      }
    }
  }
  *isamp = i; *osamp = o;
  if (p->cur >= p->npos && o == 0) return SOX_EOF;
  return SOX_SUCCESS;
}

/* ---------------- pad ---------------- */
typedef struct { double len[8]; double pos[8]; int n; sox_uint64_t pending; sox_uint64_t posn; int stage; } pad_t;

static int pad_getopts(sox_effect_t *e, char **argv, int argc)
{
  pad_t *p = calloc(1, sizeof(pad_t));
  int i;
  e->priv = p;
  if (argc < 1 || argc > 4) { sox_fail("Usage: pad {length[@position]}"); return SOX_EOF; }
  for (i = 0; i < argc; ++i) {
    char *at = strchr(argv[i], '@');
    if (at) { *at = 0; p->pos[i] = parse_pos(at+1, 1, NULL); }
    p->len[i] = parse_pos(argv[i], 1, NULL);
    ++p->n;
  }
  return SOX_SUCCESS;
}

static int pad_start(sox_effect_t *e)
{
  pad_t *p = e->priv;
  e->out_signal = e->in_signal;
  p->stage = 0; p->pending = 0; p->posn = 0;
  if (p->n) p->pending = (sox_uint64_t)(p->len[0] * e->in_signal.rate + 0.5);
  return SOX_SUCCESS;
}

static int pad_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{
  pad_t *p = e->priv;
  unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  sox_size_t max = *osamp / ch;
  sox_size_t o = 0;
  while (o < max) {
    if (p->pending) {
      sox_size_t n = (sox_size_t)(max - o < p->pending / ch ? max - o : p->pending / ch);
      memset(obuf + o*ch, 0, n * ch * sizeof(sox_sample_t));
      o += n; p->pending -= n * ch;
      if (p->pending) break;
      ++p->stage;
      p->posn = p->stage < p->n ? (sox_uint64_t)(p->pos[p->stage] * e->in_signal.rate + 0.5) : (sox_uint64_t)-1;
      continue;
    }
    if (*isamp == 0) break;
    {
      sox_size_t n = *isamp / ch;
      if (max - o < n) n = max - o;
      if (p->stage < p->n && p->posn != (sox_uint64_t)-1 && p->posn > 0) {
        sox_size_t k = (sox_size_t)(max - o);
        if ((sox_size_t)p->posn < k) k = (sox_size_t)p->posn;
        if (k > n) k = n;
