      if (p->stage >= p->n) break;
    }
  }
  *osamp = o * ch;
  return SOX_SUCCESS;
}

/* ---------------- delay ---------------- */
typedef struct { double len[8]; int n; sox_uint64_t pending; } delay_t;

static int delay_getopts(sox_effect_t *e, char **argv, int argc)
{
  delay_t *p = calloc(1, sizeof(delay_t));
  int i;
  e->priv = p;
  if (argc < 1) { sox_fail("Usage: delay {position}"); return SOX_EOF; }
  for (i = 0; i < argc; ++i) p->len[i] = parse_pos(argv[i], 1, NULL);
  p->n = argc;
  return SOX_SUCCESS;
}

static int delay_start(sox_effect_t *e)
{
  delay_t *p = e->priv;
  e->out_signal = e->in_signal;
  p->pending = (sox_uint64_t)(p->len[0] * e->in_signal.rate + 0.5);
  return SOX_SUCCESS;
}

static int delay_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{
  delay_t *p = e->priv;
  unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  sox_size_t o = 0, max = *osamp / ch;
  while (p->pending && o < max) {
    sox_size_t n = (sox_size_t)(max - o);
    if (p->pending / ch < n) n = (sox_size_t)(p->pending / ch);
    memset(obuf + o*ch, 0, n*ch*sizeof(sox_sample_t));
    o += n; p->pending -= n*ch;
  }
  {
    sox_size_t n = *isamp / ch;
    if (max - o < n) n = max - o;
    memcpy(obuf + o*ch, ibuf, n*ch*sizeof(sox_sample_t));
    o += n; *isamp = n*ch;
  }
  *osamp = o * ch;
  return SOX_SUCCESS;
}

/* ---------------- repeat ---------------- */
typedef struct { int count, done; sox_sample_t *buf; sox_size_t len, cap; } rep_t;

static int repeat_getopts(sox_effect_t *e, char **argv, int argc)
{
  rep_t *p = calloc(1, sizeof(rep_t));
  e->priv = p;
  p->count = argc ? atoi(argv[0]) : 1;
  if (p->count < 1) { sox_fail("repeat: invalid repeat count `%s'", argc ? argv[0] : ""); return SOX_EOF; }
  return SOX_SUCCESS;
}

static int repeat_start(sox_effect_t *e)
{
  rep_t *p = e->priv;
  e->out_signal = e->in_signal;
  p->done = 0; p->len = 0; p->cap = 1<<20;
  p->buf = malloc(p->cap * sizeof(sox_sample_t));
  return SOX_SUCCESS;
}

static int repeat_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{
  rep_t *p = e->priv;
  sox_size_t len = *isamp;
  (void)obuf; (void)osamp;
  if (p->len + len > p->cap) { p->cap = (p->len+len)*2; p->buf = realloc(p->buf, p->cap*sizeof(sox_sample_t)); }
  memcpy(p->buf + p->len, ibuf, len*sizeof(sox_sample_t));
  p->len += len;
  *isamp = len; *osamp = 0;
  return SOX_SUCCESS;
}

static int repeat_drain(sox_effect_t *e, sox_sample_t *obuf, sox_size_t *osamp)
{
  rep_t *p = e->priv;
  int i;
  sox_size_t total = p->len * (p->count + 1);
  sox_size_t max = *osamp;
  sox_size_t n = 0;
  for (i = 0; i <= p->count && n < max; ++i) {
    sox_size_t k = p->len < max - n ? p->len : max - n;
    memcpy(obuf + n, p->buf, k*sizeof(sox_sample_t));
    n += k;
  }
  *osamp = n;
  (void)total;
  return n == 0 ? SOX_EOF : SOX_SUCCESS;
}
