static void bq_design_LP(bq_t *p, double rate, double f, double Q)
{
  double w0 = 2*M_PI*f/rate, cs = cos(w0), sn = sin(w0), al = sn/(2*Q);
  double a0 = 1+al;
  p->b0 = ((1-cs)/2)/a0; p->b1 = (1-cs)/a0; p->b2 = ((1-cs)/2)/a0;
  p->a1 = (-2*cs)/a0; p->a2 = (1-al)/a0;
}
static void bq_design_HP(bq_t *p, double rate, double f, double Q)
{
  double w0 = 2*M_PI*f/rate, cs = cos(w0), sn = sin(w0), al = sn/(2*Q);
  double a0 = 1+al;
  p->b0 = ((1+cs)/2)/a0; p->b1 = -(1+cs)/a0; p->b2 = ((1+cs)/2)/a0;
  p->a1 = (-2*cs)/a0; p->a2 = (1-al)/a0;
}
static void bq_design_bandpass(bq_t *p, double rate, double f, double Q, int skirt)
{
  double w0 = 2*M_PI*f/rate, cs = cos(w0), sn = sin(w0), al = sn/(2*Q);
  double a0 = 1+al;
  if (skirt) { p->b0 = (sn/2)/a0; p->b1 = 0; p->b2 = (-sn/2)/a0; }
  else { p->b0 = al/a0; p->b1 = 0; p->b2 = -al/a0; }
  p->a1 = (-2*cs)/a0; p->a2 = (1-al)/a0;
}
static void bq_design_bandreject(bq_t *p, double rate, double f, double Q)
{
  double w0 = 2*M_PI*f/rate, cs = cos(w0), sn = sin(w0), al = sn/(2*Q);
