} bqarg_t;

static int bq_parse(bqarg_t *p, char **argv, int argc, int nopt)
{
  int i;
  for (i = 0; i < argc; ++i) {
    char const *a = argv[i];
    if (a[0] == '-' && a[1] && !isdigit((unsigned char)a[1])) { p->flag[strlen(a)-1] = 1; p->flag[0] = a[1]; continue; }
    if (p->v[5] != 0 && nopt == 6) continue;
    { int k = 0; while (k < 6 && p->v[k] != 0) ++k; if (k < 6) p->v[k] = atof(a); continue; }
  }
  (void)nopt;
  return 0;
}

