/* ---------------- hilbert ---------------- */
typedef struct { double *coefs; int taps; double *hist; int hp; } hil_t;
static int hilbert_getopts(sox_effect_t *e, char **argv, int argc)
{ hil_t *p = calloc(1,sizeof(hil_t)); e->priv = p;
  p->taps = argc ? atoi(argv[0]) : 255;
  if (p->taps < 3 || p->taps > 32767 || (p->taps & 1) == 0) { sox_fail("hilbert: taps must be odd, >= 3 and <= 32767"); return SOX_EOF; }
  return SOX_SUCCESS; }
static int hilbert_start(sox_effect_t *e)
{ hil_t *p = e->priv; int i, M = (p->taps - 1)/2;
  e->out_signal = e->in_signal;
  p->coefs = malloc((p->taps+1)*sizeof(double));
  for (i = 0; i <= p->taps; ++i) {
    int k = i - M;
    p->coefs[i] = (k % 2) ? 2.0/(M_PI*k) : 0;
  }
  p->hist = calloc(p->taps+1, sizeof(double));
  p->hp = 0;
  return SOX_SUCCESS; }
static int hilbert_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{ hil_t *p = e->priv; sox_size_t len = *isamp < *osamp ? *isamp : *osamp, i;
  int M = (p->taps - 1)/2, t = p->taps+1;
  for (i = 0; i < len; ++i) {
    p->hist[p->hp] = (double)ibuf[i];
    p->hp = (p->hp + 1) % t;
    { double s = 0; int j;
      for (j = 0; j < t; ++j) { double h = p->hist[(p->hp + j) % t];
        int k = j - M; s += p->coefs[j]*h; }
      (void)k;
      if (s > (double)SOX_SAMPLE_MAX) { ++e->clips; s = SOX_SAMPLE_MAX; }
      else if (s < (double)SOX_SAMPLE_MIN) { ++e->clips; s = SOX_SAMPLE_MIN; }
      obuf[i] = (sox_sample_t)s; }
  }
  *isamp = len; *osamp = len; return SOX_SUCCESS; }

/* ---------------- dcshift ---------------- */
typedef struct { double shift, limiter; int has_lim; } dcs_t;
static int dcshift_getopts(sox_effect_t *e, char **argv, int argc)
{ dcs_t *p = calloc(1,sizeof(dcs_t)); e->priv = p;
  if (argc < 1 || argc > 2) { sox_fail("Usage: dcshift shift [ limitergain ]"); return SOX_EOF; }
  p->shift = atof(argv[0]);
  if (argc == 2) { p->has_lim = 1; p->limiter = atof(argv[1]); }
  return SOX_SUCCESS; }
static int dcshift_start(sox_effect_t *e) { e->out_signal = e->in_signal; return SOX_SUCCESS; }
static int dcshift_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{ dcs_t *p = e->priv; sox_size_t len = *isamp < *osamp ? *isamp : *osamp, i;
  double shift = p->shift * SOX_SAMPLE_MAX;
  for (i = 0; i < len; ++i) { double d = ibuf[i] + shift;
    if (p->has_lim && p->limiter > 0 && p->limiter < 1) {
      double lim = SOX_SAMPLE_MAX * (1 - p->limiter);
      if (d > SOX_SAMPLE_MAX - lim) d = SOX_SAMPLE_MAX - lim*lim/(d - SOX_SAMPLE_MAX + lim);
      else if (d < SOX_SAMPLE_MIN + lim) d = SOX_SAMPLE_MIN + lim*lim/(d - SOX_SAMPLE_MIN - lim);
    }
    if (d > (double)SOX_SAMPLE_MAX) { ++e->clips; d = SOX_SAMPLE_MAX; }
    else if (d < (double)SOX_SAMPLE_MIN) { ++e->clips; d = SOX_SAMPLE_MIN; }
    obuf[i] = (sox_sample_t)d; }
  *isamp = len; *osamp = len; return SOX_SUCCESS; }

/* ---------------- contrast ---------------- */
typedef struct { double enhancement; } con_t;
static int contrast_getopts(sox_effect_t *e, char **argv, int argc)
{ con_t *p = calloc(1,sizeof(con_t)); e->priv = p;
  if (argc > 1) { sox_fail("Usage: contrast [enhancement (75)]"); return SOX_EOF; }
  p->enhancement = argc ? atof(argv[0]) : 75; return SOX_SUCCESS; }
static int contrast_start(sox_effect_t *e) { e->out_signal = e->in_signal; return SOX_SUCCESS; }
static int contrast_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{ con_t *p = e->priv; sox_size_t len = *isamp < *osamp ? *isamp : *osamp, i;
  double k = p->enhancement/100.0;
  for (i = 0; i < len; ++i) { double x = (double)ibuf[i]/SOX_SAMPLE_MAX;
    double y = x * (fabs(x) <= 0.5 ? 1 : 1);
    y = tanh(x*(1+k)/(1+k*fabs(x)));
    obuf[i] = (sox_sample_t)(y*SOX_SAMPLE_MAX); }
  *isamp = len; *osamp = len; return SOX_SUCCESS; }

/* ---------------- overdrive ---------------- */
typedef struct { double gain, colour; } odr_t;
static int overdrive_getopts(sox_effect_t *e, char **argv, int argc)
{ odr_t *p = calloc(1,sizeof(odr_t)); e->priv = p;
  if (argc > 2) { sox_fail("Usage: overdrive [gain [colour]]"); return SOX_EOF; }
  p->gain = argc ? atof(argv[0]) : 2; p->colour = argc > 1 ? atof(argv[1]) : 20; return SOX_SUCCESS; }
static int overdrive_start(sox_effect_t *e) { e->out_signal = e->in_signal; return SOX_SUCCESS; }
static int overdrive_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{ odr_t *p = e->priv; sox_size_t len = *isamp < *osamp ? *isamp : *osamp, i;
  double k = p->gain, c = p->colour;
  for (i = 0; i < len; ++i) { double x = (double)ibuf[i]/SOX_SAMPLE_MAX;
    double y = x*(1+k*fabs(x))/(1+c*x*x);
    if (y > 1) { ++e->clips; y = 1; } else if (y < -1) { ++e->clips; y = -1; }
    obuf[i] = (sox_sample_t)(y*SOX_SAMPLE_MAX); }
  *isamp = len; *osamp = len; return SOX_SUCCESS; }
