/* ---------------- hilbert ---------------- */
typedef struct { double *coefs; int taps; double *hist; int hp; } hil_t;
static int hilbert_getopts(sox_effect_t *e, char **argv, int argc)
{ hil_t *p = calloc(1,sizeof(hil_t)); e->priv = p;
  p->taps = argc ? atoi(argv[0]) : 255;
  if (p->taps < 3 || p->taps > 32767 || (p->taps & 1) == 0) { sox_fail("hilbert: taps must be odd, >= 3 and <= 32767"); return SOX_EOF; }
  return SOX_SUCCESS; }
static int hilbert_start(sox_effect_t *e)
{ hil_t *p = e->priv; int i, M = (p->taps - 1)/2;
  e->out_signal = e->in_signal;
  p->coefs = malloc((p->taps+1)*sizeof(double));
  for (i = 0; i <= p->taps; ++i) {
    int k = i - M;
    p->coefs[i] = (k % 2) ? 2.0/(M_PI*k) : 0;
  }
  p->hist = calloc(p->taps+1, sizeof(double));
  p->hp = 0;
  return SOX_SUCCESS; }
static int hilbert_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{ hil_t *p = e->priv; sox_size_t len = *isamp < *osamp ? *isamp : *osamp, i;
  int M = (p->taps - 1)/2, t = p->taps+1;
  for (i = 0; i < len; ++i) {
    p->hist[p->hp] = (double)ibuf[i];
    p->hp = (p->hp + 1) % t;
    { double s = 0; int j;
      for (j = 0; j < t; ++j) { double h = p->hist[(p->hp + j) % t];
        int k = j - M; s += p->coefs[j]*h; }
      (void)k;
      if (s > (double)SOX_SAMPLE_MAX) { ++e->clips; s = SOX_SAMPLE_MAX; }
      else if (s < (double)SOX_SAMPLE_MIN) { ++e->clips; s = SOX_SAMPLE_MIN; }
      obuf[i] = (sox_sample_t)s; }
  }
  *isamp = len; *osamp = len; return SOX_SUCCESS; }

