typedef struct { double shift, limiter; int has_lim; } dcs_t;
static int dcshift_getopts(sox_effect_t *e, char **argv, int argc)
{ dcs_t *p = calloc(1,sizeof(dcs_t)); e->priv = p;
  if (argc < 1 || argc > 2) { sox_fail("Usage: dcshift shift [ limitergain ]"); return SOX_EOF; }
  p->shift = atof(argv[0]);
  if (argc == 2) { p->has_lim = 1; p->limiter = atof(argv[1]); }
  return SOX_SUCCESS; }
static int dcshift_start(sox_effect_t *e) { e->out_signal = e->in_signal; return SOX_SUCCESS; }
static int dcshift_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{ dcs_t *p = e->priv; sox_size_t len = *isamp < *osamp ? *isamp : *osamp, i;
  double shift = p->shift * SOX_SAMPLE_MAX;
  for (i = 0; i < len; ++i) { double d = ibuf[i] + shift;
    if (p->has_lim && p->limiter > 0 && p->limiter < 1) {
      double lim = SOX_SAMPLE_MAX * (1 - p->limiter);
      if (d > SOX_SAMPLE_MAX - lim) d = SOX_SAMPLE_MAX - lim*lim/(d - SOX_SAMPLE_MAX + lim);
      else if (d < SOX_SAMPLE_MIN + lim) d = SOX_SAMPLE_MIN + lim*lim/(d - SOX_SAMPLE_MIN - lim);
    }
    if (d > (double)SOX_SAMPLE_MAX) { ++e->clips; d = SOX_SAMPLE_MAX; }
    else if (d < (double)SOX_SAMPLE_MIN) { ++e->clips; d = SOX_SAMPLE_MIN; }
    obuf[i] = (sox_sample_t)d; }
  *isamp = len; *osamp = len; return SOX_SUCCESS; }

