  p->enhancement = argc ? atof(argv[0]) : 75; return SOX_SUCCESS; }
static int contrast_start(sox_effect_t *e) { e->out_signal = e->in_signal; return SOX_SUCCESS; }
static int contrast_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{ con_t *p = e->priv; sox_size_t len = *isamp < *osamp ? *isamp : *osamp, i;
  double k = p->enhancement/100.0;
  for (i = 0; i < len; ++i) { double x = (double)ibuf[i]/SOX_SAMPLE_MAX;
    double y = x * (fabs(x) <= 0.5 ? 1 : 1);
    y = tanh(x*(1+k)/(1+k*fabs(x)));
    obuf[i] = (sox_sample_t)(y*SOX_SAMPLE_MAX); }
  *isamp = len; *osamp = len; return SOX_SUCCESS; }

