static int overdrive_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{ odr_t *p = e->priv; sox_size_t len = *isamp < *osamp ? *isamp : *osamp, i;
  double k = p->gain, c = p->colour;
