/* ---------------- biquad based filters ---------------- */
typedef struct {
  double b0, b1, b2, a1, a2;
  double *sx1, *sx2, *sy1, *sy2;
  double x1, x2, y1, y2;
  unsigned ch;
} bq_t;

static void bq_init(bq_t *p, unsigned ch)
{
  p->ch = ch;
  p->x1 = p->x2 = p->y1 = p->y2 = 0;
  if (ch > 1) {
    p->sx1 = calloc(ch, sizeof(double)); p->sx2 = calloc(ch, sizeof(double));
    p->sy1 = calloc(ch, sizeof(double)); p->sy2 = calloc(ch, sizeof(double));
  }
}

static void bq_design_LP(bq_t *p, double rate, double f, double Q)
{ double w0 = 2*M_PI*f/rate, cs = cos(w0), sn = sin(w0), al = sn/(2*Q), a0 = 1+al;
  p->b0 = ((1-cs)/2)/a0; p->b1 = (1-cs)/a0; p->b2 = ((1-cs)/2)/a0;
  p->a1 = (-2*cs)/a0; p->a2 = (1-al)/a0; }
static void bq_design_HP(bq_t *p, double rate, double f, double Q)
{ double w0 = 2*M_PI*f/rate, cs = cos(w0), sn = sin(w0), al = sn/(2*Q), a0 = 1+al;
  p->b0 = ((1+cs)/2)/a0; p->b1 = -(1+cs)/a0; p->b2 = ((1+cs)/2)/a0;
  p->a1 = (-2*cs)/a0; p->a2 = (1-al)/a0; }
static void bq_design_bandpass(bq_t *p, double rate, double f, double Q, int skirt)
{ double w0 = 2*M_PI*f/rate, cs = cos(w0), sn = sin(w0), al = sn/(2*Q), a0 = 1+al;
  if (skirt) { p->b0 = (sn/2)/a0; p->b1 = 0; p->b2 = (-sn/2)/a0; }
  else { p->b0 = al/a0; p->b1 = 0; p->b2 = -al/a0; }
  p->a1 = (-2*cs)/a0; p->a2 = (1-al)/a0; }
static void bq_design_bandreject(bq_t *p, double rate, double f, double Q)
{ double w0 = 2*M_PI*f/rate, cs = cos(w0), sn = sin(w0), al = sn/(2*Q), a0 = 1+al;
  p->b0 = 1/a0; p->b1 = (-2*cs)/a0; p->b2 = 1/a0;
  p->a1 = (-2*cs)/a0; p->a2 = (1-al)/a0; }
static void bq_design_allpass(bq_t *p, double rate, double f, double Q)
{ double w0 = 2*M_PI*f/rate, cs = cos(w0), sn = sin(w0), al = sn/(2*Q), a0 = 1+al;
  p->b0 = (1-al)/a0; p->b1 = (-2*cs)/a0; p->b2 = (1+al)/a0;
  p->a1 = (-2*cs)/a0; p->a2 = (1-al)/a0; }
static void bq_design_peaking(bq_t *p, double rate, double f, double Q, double dBgain)
{ double A = pow(10, dBgain/40), w0 = 2*M_PI*f/rate, cs = cos(w0), sn = sin(w0), al = sn/(2*Q), a0 = 1+al/A;
  p->b0 = (1+al*A)/a0; p->b1 = (-2*cs)/a0; p->b2 = (1-al*A)/a0;
  p->a1 = (-2*cs)/a0; p->a2 = (1-al/A)/a0; }
static void bq_design_lowshelf(bq_t *p, double rate, double f, double S, double dBgain)
{ double A = pow(10, dBgain/40), w0 = 2*M_PI*f/rate, cs = cos(w0), sn = sin(w0);
  double al = sn/2 * sqrt((A + 1/A)*(1/S - 1) + 2), twoSQ = 2*sqrt(A)*al, a0 = (A+1) + (A-1)*cs + twoSQ;
  p->b0 = (A*((A+1) - (A-1)*cs + twoSQ))/a0; p->b1 = (2*A*((A-1) - (A+1)*cs))/a0;
  p->b2 = (A*((A+1) - (A-1)*cs - twoSQ))/a0; p->a1 = (-2*((A-1) + (A+1)*cs))/a0;
  p->a2 = ((A+1) + (A-1)*cs - twoSQ)/a0; }
static void bq_design_highshelf(bq_t *p, double rate, double f, double S, double dBgain)
{ double A = pow(10, dBgain/40), w0 = 2*M_PI*f/rate, cs = cos(w0), sn = sin(w0);
  double al = sn/2 * sqrt((A + 1/A)*(1/S - 1) + 2), twoSQ = 2*sqrt(A)*al, a0 = (A+1) - (A-1)*cs + twoSQ;
  p->b0 = (A*((A+1) + (A-1)*cs + twoSQ))/a0; p->b1 = (-2*A*((A-1) + (A+1)*cs))/a0;
  p->b2 = (A*((A+1) + (A-1)*cs - twoSQ))/a0; p->a1 = (2*((A-1) - (A+1)*cs))/a0;
  p->a2 = ((A+1) - (A-1)*cs - twoSQ)/a0; }

static double Q_from_width(char const *spec, double freq)
{ char *end; double w = strtod(spec, &end); char t = *end;
  if (t == 'k') { w *= 1000; t = 'h'; }
  switch (t) {
    case 'q': return w;
    case 'o': { double c = pow(2.0, w); return sqrt(c)/(c-1); }
    case 'h': return freq / w;
    default: return w;
  } }

static double width_hz(char const *spec)
{ char *end; double w = strtod(spec, &end); if (*end == 'k') w *= 1000; return w; }

static int bq_flow_common(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{
  bq_t *p = e->priv;
  unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  sox_size_t len = *isamp < *osamp ? *isamp : *osamp, i;
  for (i = 0; i < len; ++i) {
    int c = (int)(i % ch);
    double *x1 = ch > 1 ? &p->sx1[c] : &p->x1, *x2 = ch > 1 ? &p->sx2[c] : &p->x2;
    double *y1 = ch > 1 ? &p->sy1[c] : &p->y1, *y2 = ch > 1 ? &p->sy2[c] : &p->y2;
    double x0 = (double)ibuf[i];
    double y = p->b0*x0 + p->b1**x1 + p->b2**x2 - p->a1**y1 - p->a2**y2;
    *x2 = *x1; *x1 = x0; *y2 = *y1; *y1 = y;
    if (y > (double)SOX_SAMPLE_MAX) { ++e->clips; y = SOX_SAMPLE_MAX; }
    else if (y < (double)SOX_SAMPLE_MIN) { ++e->clips; y = SOX_SAMPLE_MIN; }
    obuf[i] = (sox_sample_t)y;
  }
  *isamp = len; *osamp = len;
  return SOX_SUCCESS;
}

