/* ---------------- echo / echos ---------------- */
typedef struct { int ndelay; double in_gain, out_gain; double delay[16], decay[16]; double *y; sox_size_t ylen; } echo_t;

static int echo_getopts(sox_effect_t *e, char **argv, int argc)
{ echo_t *p = calloc(1,sizeof(echo_t)); e->priv = p;
  if (argc < 4 || (argc - 2) % 2) { sox_fail("Usage: echo gain-in gain-out delay decay [ delay decay ... ]"); return SOX_EOF; }
  p->in_gain = atof(argv[0]); p->out_gain = atof(argv[1]);
  p->ndelay = (argc - 2)/2;
  { int i; for (i = 0; i < p->ndelay; ++i) { p->delay[i] = atof(argv[2+2*i]); p->decay[i] = atof(argv[3+2*i]); } }
  return SOX_SUCCESS; }
static int echo_start(sox_effect_t *e)
{ echo_t *p = e->priv; int i; sox_rate_t rate = e->in_signal.rate;
  e->out_signal = e->in_signal;
  for (i = 0; i < p->ndelay; ++i) p->delay[i] = p->delay[i] * rate / 1000;
  { sox_size_t maxd = 0; for (i = 0; i < p->ndelay; ++i) if (p->delay[i] > maxd) maxd = p->delay[i];
    p->ylen = (sox_size_t)maxd + 1;
    p->y = calloc(p->ylen, sizeof(double)); }
  return SOX_SUCCESS; }
static int echo_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{ echo_t *p = e->priv; unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  sox_size_t len = *isamp < *osamp ? *isamp : *osamp, i;
  for (i = 0; i < len; ++i) {
    int c = (int)(i % ch);
    double out = (double)ibuf[i] * p->in_gain;
    int j;
    for (j = 0; j < p->ndelay; ++j) {
      sox_size_t d = (sox_size_t)p->delay[j] * ch + c;
      if (d < p->ylen) out += p->y[d] * p->decay[j];
    }
    { sox_size_t d = c; if (d < p->ylen) p->y[d] = out; else p->y[c % p->ylen] = out; }
    if (out > (double)SOX_SAMPLE_MAX) { ++e->clips; out = SOX_SAMPLE_MAX; }
    else if (out < (double)SOX_SAMPLE_MIN) { ++e->clips; out = SOX_SAMPLE_MIN; }
    obuf[i] = (sox_sample_t)(out * p->out_gain / p->in_gain);
  }
  *isamp = len; *osamp = len; return SOX_SUCCESS; }

/* ---------------- tremolo ---------------- */
typedef struct { double speed, depth; double phase; } trm_t;
static int tremolo_getopts(sox_effect_t *e, char **argv, int argc)
{ trm_t *p = calloc(1,sizeof(trm_t)); e->priv = p;
  if (argc != 2) { sox_fail("Usage: tremolo speed_Hz [depth_percent]"); return SOX_EOF; }
  p->speed = atof(argv[0]); p->depth = atof(argv[1]) / 100.0;
  if (p->depth < 0 || p->depth > 1) { sox_fail("tremolo: depth must be between 0 and 100"); return SOX_EOF; }
  return SOX_SUCCESS; }
static int tremolo_start(sox_effect_t *e)
{ trm_t *p = e->priv; e->out_signal = e->in_signal;
  p->phase = 0; p->depth = 0.5 + p->depth/2;
  e->extra = 1; return SOX_SUCCESS; }
static int tremolo_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{ trm_t *p = e->priv; sox_size_t len = *isamp < *osamp ? *isamp : *osamp, i;
  double rate = e->in_signal.rate, inc = 2*M_PI*p->speed/rate;
  for (i = 0; i < len; ++i) {
    double d = (1 - p->depth) + p->depth * (0.5 - 0.5*cos(p->phase));
    double v = ibuf[i] * d;
    p->phase += inc;
    if (p->phase > 2*M_PI) p->phase -= 2*M_PI;
    obuf[i] = (sox_sample_t)v;
  }
  *isamp = len; *osamp = len; return SOX_SUCCESS; }

/* ---------------- speed ---------------- */
typedef struct { double factor; } spd_t;
static int speed_getopts(sox_effect_t *e, char **argv, int argc)
{ spd_t *p = calloc(1,sizeof(spd_t)); e->priv = p;
  if (argc != 1) { sox_fail("Usage: speed factor[c]"); return SOX_EOF; }
  { char *end; double f = strtod(argv[0], &end);
    if (*end == 'c') p->factor = 1.0/f; else p->factor = f; }
  if (p->factor <= 0) { sox_fail("speed: factor must be > 0"); return SOX_EOF; }
  return SOX_SUCCESS; }
