{ (void)e; (void)ibuf; (void)obuf; (void)isamp; (void)osamp; return SOX_SUCCESS; }

/* ---------------- swap ---------------- */
static int swap_getopts(sox_effect_t *e, char **argv, int argc)
{ (void)e; (void)argv; if (argc) { sox_fail("Usage: swap"); return SOX_EOF; } return SOX_SUCCESS; }
static int swap_start(sox_effect_t *e)
{ e->out_signal = e->in_signal;
  if (e->in_signal.channels != 2) { sox_fail("swap: can't swap channels other than stereo"); return SOX_EOF; }
  return SOX_SUCCESS; }
static int swap_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{ sox_size_t len = *isamp < *osamp ? *isamp : *osamp, i;
  for (i = 0; i < len; i += 2) { sox_sample_t t = ibuf[i]; obuf[i] = ibuf[i+1]; obuf[i+1] = t; }
  *isamp = len; *osamp = len; return SOX_SUCCESS; }

/* ---------------- downsample / upsample ---------------- */
typedef struct { int factor; sox_size_t count; } dsm_t;
static int downsample_getopts(sox_effect_t *e, char **argv, int argc)
{ dsm_t *p = calloc(1,sizeof(dsm_t)); e->priv = p; p->factor = argc ? atoi(argv[0]) : 2;
  if (p->factor < 1) { sox_fail("downsample: factor must be an integer greater than or equal to one"); return SOX_EOF; }
  return SOX_SUCCESS; }
static int downsample_start(sox_effect_t *e)
{ dsm_t *p = e->priv; e->out_signal = e->in_signal;
  e->out_signal.rate = e->in_signal.rate / p->factor; e->extra = 1; return SOX_SUCCESS; }
static int downsample_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{ dsm_t *p = e->priv; unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  sox_size_t i, o = 0;
  for (i = 0; i < *isamp; i += ch*p->factor) {
    sox_size_t k; for (k = 0; k < ch; ++k) obuf[o++] = ibuf[i+k];
  }
  *isamp = i; *osamp = o; return SOX_SUCCESS; }
static int upsample_getopts(sox_effect_t *e, char **argv, int argc)
{ dsm_t *p = calloc(1,sizeof(dsm_t)); e->priv = p; p->factor = argc ? atoi(argv[0]) : 2;
  if (p->factor < 1) { sox_fail("upsample: factor must be an integer greater than or equal to one"); return SOX_EOF; }
  return SOX_SUCCESS; }
static int upsample_start(sox_effect_t *e)
{ dsm_t *p = e->priv; e->out_signal = e->in_signal;
  e->out_signal.rate = e->in_signal.rate * p->factor; e->extra = 1; return SOX_SUCCESS; }
static int upsample_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{ dsm_t *p = e->priv; unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  sox_size_t i, o = 0;
  for (i = 0; i + ch <= *isamp && o + ch*p->factor <= *osamp; i += ch) {
    sox_size_t k, f;
    for (f = 0; f < (sox_size_t)p->factor; ++f)
      for (k = 0; k < ch; ++k) obuf[o++] = ibuf[i+k];
  }
  *isamp = i; *osamp = o; return SOX_SUCCESS; }

/* ---------------- dither ---------------- */
typedef struct { int precision; uint64_t rng; int shaped; sox_bool auto_dither; } dth_t;

static uint64_t dth_rand(dth_t *p)
{
  p->rng ^= p->rng << 13; p->rng ^= p->rng >> 7; p->rng ^= p->rng << 17;
  return p->rng;
}

static int dither_getopts(sox_effect_t *e, char **argv, int argc)
{ dth_t *p = calloc(1,sizeof(dth_t)); e->priv = p; int i;
  for (i = 0; i < argc; ++i) {
    char const *a = argv[i];
    if (a[0] == '-' && a[1]) {
      switch (a[1]) {
        case 'S': p->shaped = 0; break;
        case 's': p->shaped = 1; break;
        case 'a': p->auto_dither = sox_true; break;
        case 'p': if (i+1 < argc) { p->precision = atoi(argv[++i]); } break;
        case 'f': if (i+1 < argc) ++i; break;
        default: sox_fail("Usage: dither [-S|-s|-f filter] [-a] [-p precision]"); return SOX_EOF;
      }
    } else { sox_fail("Usage: dither [-S|-s|-f filter] [-a] [-p precision]"); return SOX_EOF; }
  }
  return SOX_SUCCESS; }
static int dither_start(sox_effect_t *e)
{ dth_t *p = e->priv;
  e->out_signal = e->in_signal;
  p->precision = e->out_signal.precision;
  p->rng = sox_globals.repeatable ? 0x1234abcdUL : (uint64_t)time(NULL);
  return SOX_SUCCESS; }
static int dither_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{ dth_t *p = e->priv; sox_size_t len = *isamp < *osamp ? *isamp : *osamp, i;
  for (i = 0; i < len; ++i) {
    uint64_t r = dth_rand(p);
    uint32_t a = (uint32_t)(r >> 32), b = (uint32_t)r;
    uint64_t sum = (uint64_t)a + b;
    int n = (sum < 0x80000000ULL) ? -1 : (sum < 0x180000000ULL ? 0 : 1);
    obuf[i] = ibuf[i] + n;
  }
  *isamp = len; *osamp = len; return SOX_SUCCESS; }
