  for (i = 0; i < max; ++i) {
    for (o = 0; o < p->ochannels; ++o) {
      double d = 0; int k;
      for (k = 0; k < p->spec[o].n; ++k) {
        int c = p->spec[o].in[k] - 1;
        double v = p->spec[o].vol[k];
        if (c >= 0 && c < (int)ich) {
