  double meanabs = p->sumabs / n / SOX_SAMPLE_MAX;
  double rms = sqrt(p->sumsqr / n) / SOX_SAMPLE_MAX;
  double maxd = p->maxd / SOX_SAMPLE_MAX, mind = p->mind / SOX_SAMPLE_MAX;
  double meand = p->sumd / (n-1) / SOX_SAMPLE_MAX;
  double rmsd = sqrt(p->sumsqr_d / (n-1)) / SOX_SAMPLE_MAX;
  double voladj = max != 0 ? 1.0 / max : 0;
  double scale = p->rms ? rms : 1;
  sox_report("Samples read: %18.0f", n);
  sox_report("Length (seconds): %14.6f", n / e->in_signal.channels / e->in_signal.rate);
  sox_report("Scaled by: %21.1f", SOX_SAMPLE_MAX * scale);
  sox_report("Maximum amplitude: %13.6f", max);
