static int synth_start(sox_effect_t *e)
{ syn_t *p = e->priv;
  e->out_signal = e->in_signal;
  if (p->length_d == 0) { sox_fail("synth: no length given"); return SOX_EOF; }
  p->length = (sox_uint64_t)(p->length_d * e->in_signal.rate);
  p->nsamp = 0;
  { int i; for (i = 0; i < 8; ++i) p->phi[i] = 0; }
