    p->nchan = 1;
    p->chan[0].type = 0; p->chan[0].freq = 440; p->chan[0].freq2 = 440;
    p->chan[0].offset = 0; p->chan[0].phase = 0; p->chan[0].combine = 0;
  }
  return SOX_SUCCESS; }

static double synth_gen(int type, double t)
{
  switch (type) {
    case 0: return sin(t);
    case 1: return (fmod(t/(2*M_PI), 1.0) < 0.5) ? 1 : -1;
    case 2: { double f = fmod(t/(2*M_PI), 1.0); return f < 0.25 ? 4*f : f < 0.75 ? 2-4*f : 4*f-4; }
    case 3: { double f = fmod(t/(2*M_PI), 1.0); return 2*f-1; }
    default: return sin(t);
  }
}

static int synth_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{ syn_t *p = e->priv; unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  sox_size_t i, o = 0;
  (void)ibuf;
  for (i = 0; i < *osamp/ch && p->nsamp < p->length; ++i) {
    unsigned c;
    for (c = 0; c < ch; ++c) {
      double v = 0;
      int k;
      for (k = 0; k < p->nchan; ++k) {
        double f = p->chan[k].freq;
        double ph = p->phi[c] + p->chan[k].phase * 2 * M_PI / 360;
        double s = synth_gen(p->chan[k].type, ph) * 0.3;
        v += s;
      }
      if (v > 1) v = 1; else if (v < -1) v = -1;
      obuf[o++] = (sox_sample_t)(v * SOX_SAMPLE_MAX);
      ++p->phi[c];
      p->phi[c] = fmod(p->phi[c] * 2*M_PI*f/e->in_signal.rate, 2*M_PI);
    }
