static double sinc_window(double x, double beta, int n)
{ /* Lanczos / Kaiser windowed sinc */
  if (fabs(x) >= n) return 0;
  if (x == 0) return 1;
  return sin(M_PI*x)/(M_PI*x) * pow(cos(M_PI*x/(2*n)), beta);
}

static int rate_getopts(sox_effect_t *e, char **argv, int argc)
{ rate_t *p = calloc(1,sizeof(rate_t)); e->priv = p; int i;
