static int chorus_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{ chor_t *p = e->priv; sox_size_t len = *isamp < *osamp ? *isamp : *osamp, i;
  sox_rate_t rate = e->in_signal.rate;
  unsigned ch = p->ch;
  for (i = 0; i < len; ++i) {
    int c = (int)(i % ch);
    sox_size_t idx = (p->pos + (sox_size_t)(p->delay[0]*rate/1000)) % p->blen;
    double delayed = p->buf[idx*ch + c];
    double sweep = p->depth * (0.5 - 0.5*cos(2*M_PI*p->phase));
    sox_size_t didx = (sox_size_t)(((double)p->pos + p->delay[0]*rate/1000 - sweep*rate/1000) + p->blen) % p->blen;
    double d2 = p->buf[didx*ch + c];
    double out = (double)ibuf[i]*p->in_gain + (delayed - d2) * p->decay[0];
    p->buf[(p->pos % p->blen)*ch + c] = (double)ibuf[i] * p->in_gain;
    if (i % ch == (int)ch - 1) { ++p->pos; p->phase += 2*M_PI*p->speed/rate; if (p->phase > 2*M_PI) p->phase -= 2*M_PI; }
    if (out > (double)SOX_SAMPLE_MAX) { ++e->clips; out = SOX_SAMPLE_MAX; }
    else if (out < (double)SOX_SAMPLE_MIN) { ++e->clips; out = SOX_SAMPLE_MIN; }
    obuf[i] = (sox_sample_t)(out*p->out_gain);
  }
  *isamp = len; *osamp = len; return SOX_SUCCESS; }

