static int reverb_getopts(sox_effect_t *e, char **argv, int argc)
{ revb_t *p = calloc(1,sizeof(revb_t)); e->priv = p; int i;
  for (i = 0; i < argc; ++i) {
    if (!strncmp(argv[i],"-w",2) || !strncmp(argv[i],"--wet-only",10)) p->wet_only = 1;
    else { switch (i) { case 0: p->reverberance = atof(argv[i]); break; case 1: p->hf = atof(argv[i]); break;
      case 2: p->roomscale = atof(argv[i]); break; case 3: p->depth = atof(argv[i]); break;
      case 4: p->predelay = atof(argv[i]); break; case 5: p->wet = atof(argv[i]); break; } }
  }
  return SOX_SUCCESS; }
static int reverb_start(sox_effect_t *e)
{ revb_t *p = e->priv; sox_rate_t rate = e->in_signal.rate;
  static const double delays[8] = {111, 47, 83, 71, 173, 131, 29, 233};
  int i;
  e->out_signal = e->in_signal;
  p->ch = e->in_signal.channels ? e->in_signal.channels : 1;
  for (i = 0; i < 8; ++i) {
    p->blen[i] = (sox_size_t)(delays[i] * rate / 1000 * (p->roomscale ? p->roomscale/100 : 1)) + 1;
    if (p->blen[i] < 1) p->blen[i] = 1;
