static int reverb_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{ revb_t *p = e->priv; sox_size_t len = *isamp < *osamp ? *isamp : *osamp, i;
  unsigned ch = p->ch;
  double fb = p->reverberance/100.0;
  for (i = 0; i < len; ++i) {
    int c = (int)(i % ch);
    double in = (double)ibuf[i]/(double)SOX_SAMPLE_MAX;
    double out = in;
    int k;
    for (k = 0; k < 8; ++k) {
      sox_size_t idx = (p->pos[k] + 1) % p->blen[k];
      double d = p->buf[k][idx];
      p->buf[k][p->pos[k]] = in * fb + d * fb * 0.7;
      if (++p->pos[k] >= p->blen[k]) p->pos[k] = 0;
      out += d * (p->wet_only ? 1 : 0.5);
    }
    if (out > 1) { ++e->clips; out = 1; } else if (out < -1) { ++e->clips; out = -1; }
    obuf[i] = (sox_sample_t)(out * SOX_SAMPLE_MAX);
  }
  *isamp = len; *osamp = len; return SOX_SUCCESS; }
