static sox_size_t rate_hist_push(rate_t *p, double const *vals, unsigned ch)
{
  sox_size_t k;
  for (k = 0; k < ch; ++k) {
    double *h = p->history + k*p->hlen;
    memmove(h, h+1, (p->hlen-1)*sizeof(double));
    h[p->hlen-1] = vals[k];
  }
  p->ilen++;
