static int rate_flow(sox_effect_t *e, const sox_sample_t *ibuf, sox_sample_t *obuf, sox_size_t *isamp, sox_size_t *osamp)
{ rate_t *p = e->priv;
  unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  sox_size_t maxo = *osamp / ch;
  sox_size_t o = 0;
  int half = p->taps/2;
  double inv = 1.0 / p->factor;
  double cutoff = p->factor < 1 ? p->factor : 1;
  sox_size_t i;
  for (i = 0; i + ch <= *isamp && o < maxo; ) {
    /* push one input frame */
    { sox_size_t k; double vals[8];
      for (k = 0; k < ch && k < 8; ++k) vals[k] = (double)ibuf[i+k];
      rate_hist_push(p, vals, ch > 8 ? 8 : ch);
      i += ch; }
    /* emit output samples while possible */
    while (o < maxo && p->ilen - 1 >= (sox_size_t)(p->phase + half)) {
      double t = p->phase;
