    secs -= h*3600; m = (unsigned)(secs/60); s = (unsigned)(secs - m*60);
    frac = secs - m*60 - s;
    printf("Duration       : %02u:%02u:%02u.%02u = %llu samples ~ %.5f CDDA sectors\n",
           h, m, s, (unsigned)(frac*100), (unsigned long long)len, len/588.0);
  }
