    sox_uint64_t sz = fsize(ft);
    double kb = sz / 1024.0;
    double br = sz * 8.0 / (len / rate) / 1000;
    if (kb >= 100) printf("File Size      : %.2fk\n", kb/1000.0*1000/1000*1000 >= 1000 ? kb : kb);
    else printf("File Size      : %.2fk\n", kb);
    printf("Bit Rate       : %uk\n", (unsigned)(br));
