        printf("%02u:%02u:%02u.%02u\n", h, m, s, (unsigned)(frac*100));
      }
      if (opt_D) printf("%f\n", fo.ft->length / fo.ft->signal.rate);
      if (opt_b) printf("%u\n", sox_encoding_bits_per_sample(fo.ft->encoding.encoding, fo.ft->encoding.precision));
      if (opt_B) {
