        printf("%uk\n", (unsigned)(br+0.5));
      }
      if (opt_p) printf("%u\n", fo.ft->signal.precision);
      if (opt_e) printf("%s\n", sox_encoding_name(fo.ft->encoding.encoding));
      if (opt_a) printf("%s\n", fo.ft->encoding.comment ? fo.ft->encoding.comment : "");
      if (!opt_t && !opt_r && !opt_c && !opt_s && !opt_d && !opt_D && !opt_b && !opt_B && !opt_p && !opt_e && !opt_a)
        soxi_show(fo.ft);
      tot_s += fo.ft->length; tot_d += fo.ft->length / fo.ft->signal.rate;
      any = 1;
    }
    (void)tot_s; (void)tot_d; (void)any; (void)opt_T;
  }
  free(files);
  return 0;
}
