/* ---------- option parsing ---------- */
static int parse_opts(int argc, char **argv, int *effects_start, int *nfiles_pos)
{
  int i = 0;
  *effects_start = argc;
  *nfiles_pos = argc;
  new_fopt();
  while (i < argc) {
    char *a = argv[i];
    if (a[0] == '-' && a[1]) {
      int consumed = 1;
      if (a[1] == '-') {
        /* long option */
        char namebuf[64]; char *eq;
        int ni = 0, k, idx, ambig[8], nambig = 0;
        char const *val = NULL;
        strncpy(namebuf, a+2, 63); namebuf[63] = 0;
        eq = strchr(namebuf, '=');
        if (eq) { *eq = 0; val = a + 2 + (eq - namebuf) + 1; }
        for (k = 0; namebuf[k]; ++k) if (namebuf[k] == '=') { namebuf[k] = 0; }
        if (!namebuf[0]) { i += 1; continue; }
        idx = longopt_index(namebuf, ambig, &nambig);
        if (idx < 0) {
          if (nambig > 1) {
            int q;
            sox_warn("getopt: parameter `--%s' is ambiguous:", namebuf);
            for (q = 0; q < nambig; ++q) sox_warn("getopt: parameter `--%s' could be `--%s'", namebuf, opts[ambig[q]].name);
          } else sox_warn("getopt: parameter not recognized from `--%s'", a+2);
          sox_fail("sox: invalid option");
          usage();
          return -1;
        }
        if (opts[idx].has_arg == OA_REQ && !val) {
          if (i+1 < argc) { val = argv[i+1]; consumed = 2; }
          else { sox_warn("getopt: `%s' requires an argument from `--%s'", namebuf, a+2);
                 sox_fail("sox: invalid option"); usage(); return -1; }
        }
        if (handle_option(opts[idx].kind, val, namebuf) < 0) { sox_fail("sox: invalid option"); usage(); return -1; }
      } else {
        /* short options */
        char const *p = a+1;
        while (*p) {
          char c = *p++;
          int j, found = -1;
          for (j = 0; opts[j].name; ++j) if (opts[j].shortopt == c) { found = j; break; }
          if (found < 0) {
            /* other short opts */
            sox_warn("getopt: option `%c' not recognized", c);
            sox_fail("sox: invalid option");
            usage();
            return -1;
          }
          {
            char const *val = NULL;
            if (opts[found].has_arg == OA_REQ) {
              if (*p) { val = p; p += strlen(p); }
              else if (i+1 < argc) { val = argv[i+1]; consumed = 2; }
              else { sox_warn("getopt: option `%c' requires an argument", c); sox_fail("sox: invalid option"); usage(); return -1; }
            } else if (opts[found].has_arg == OA_OPT) {
              if (*p) { val = p; p += strlen(p); }
              else if (i+1 < argc && isdigit((unsigned char)argv[i+1][0])) { val = argv[i+1]; consumed = 2; }
            }
            if (handle_shortopt(c, val) < 0) { sox_fail("sox: invalid option"); usage(); return -1; }
          }
        }
      }
      i += consumed;
      continue;
    }
    /* non-option */
    if (nfopts > 0 && fopts[nfopts-1].filename == NULL) {
      /* is this an effect? */
      if (sox_effect_find(a) >= 0) {
        *effects_start = i;
        *nfiles_pos = i;
        return i;
      }
      fopts[nfopts-1].filename = a;
      ++i;
      new_fopt();
      continue;
    }
    fopts[nfopts-1].filename = a;
    ++i;
    new_fopt();
  }
  *effects_start = argc;
  return argc;
}
