    case O_VOLUMEN: {
      char *end; double v = strtod(val, &end);
      if (end == val) { sox_fail("Volume value `%s' is not a number", val); return -1; }
      fopts[nfopts-1].volume = v; fopts[nfopts-1].volume_given = 1;
