      fopts[nfopts-1].encoding.precision = 0;
      fopts[nfopts-1].encoding_bits = (unsigned)v;
      fopts[nfopts-1].bits_given = 1;
    } break;
    case O_REVERSEBITS: fopts[nfopts-1].encoding.reverse_bits = 1; break;
    case O_REVERSENibbles: fopts[nfopts-1].encoding.reverse_nibbles = 1; break;
