    case O_NULL: fopts[nfopts-1].filename = xstrdup("-"); fopts[nfopts-1].type = xstrdup("null"); new_fopt(); break;
    case O_PIPE: fopts[nfopts-1].filename = xstrdup("-"); fopts[nfopts-1].type = xstrdup("sox"); new_fopt(); break;
    default: sox_warn("getopt: parameter not recognized from `--%s'", name); return -1;
  }
