}

static int handle_shortopt(char c, char const *val)
{
  int i;
  for (i = 0; opts[i].name; ++i) if (opts[i].shortopt == c) return handle_option(opts[i].kind, val, opts[i].name);
  switch (c) {
    case 'L': fopts[nfopts-1].encoding.opposite_endian = 0; return 0;
    case 'B': fopts[nfopts-1].encoding.opposite_endian = 1; return 0;
    case 'x': fopts[nfopts-1].encoding.opposite_endian = 2; return 0;
    case 'm': sox_globals.combine_method = 2; return 0;
    case 'M': sox_globals.combine_method = 4; return 0;
    case 'T': sox_globals.combine_method = 5; return 0;
    case 'R': sox_globals.repeatable = 1; return 0;
    case 'V':
      if (val) sox_globals.verbosity = atoi(val);
      else ++sox_globals.verbosity;
      if (sox_globals.verbosity >= 3) printf("%s:      SoX v%s\n", sox_globals.argv0, "14.4.2");
      return 0;
    default: return 0;
  }
}

void usage(void) { print_help(); }
