/* ---------- the effect chain driver ---------- */
typedef struct { sox_effect_t *e[64]; int n; } chain_t;

static void chain_add(chain_t *c, sox_effect_t *e)
{ c->e[c->n++] = e; }

static sox_size_t run_flow(sox_effect_t *e, const sox_sample_t *ib, sox_sample_t *ob, sox_size_t is, sox_size_t os)
{ sox_size_t a = is, b = os;
  e->handler->flow(e, ib, ob, &a, &b);
  return b; }

static void display_file_info(sox_format_t *ft, int is_output)
{
  fprintf(stderr, "\n%s File    : '%s'", is_output ? "Output" : "Input", ft->filename);
  if (strcmp(ft->type, "raw") == 0 && !strchr(ft->filename,'.')) fprintf(stderr, " (raw)");
  fprintf(stderr, "\n");
  fprintf(stderr, "Channels       : %u\n", ft->signal.channels);
  fprintf(stderr, "Sample Rate    : %u\n", (unsigned)(ft->signal.rate + 0.5));
  fprintf(stderr, "Precision      : %u-bit\n", ft->signal.precision);
  {
    double secs = ft->length / ft->signal.rate;
    unsigned h = (unsigned)(secs/3600), m, s; double frac;
    unsigned long long cd = (unsigned long long)(ft->length/588.0*75/75);
    secs -= h*3600; m = (unsigned)(secs/60); s = (unsigned)(secs-m*60); frac = secs-m*60-s;
    fprintf(stderr, "Duration       : %02u:%02u:%02u.%02u = %llu samples %s %.5f CDDA sectors\n",
            h, m, s, (unsigned)(frac*100), (unsigned long long)ft->length,
            is_output ? "=" : "~", ft->length / ft->signal.rate * 75.0);
    (void)cd;
  }
  if (!is_output) {
    sox_uint64_t sz = fsize_pub(ft);
    fprintf(stderr, "File Size      : %.3gk\n", sz/1000.0);
    fprintf(stderr, "Bit Rate       : %.3gk\n", ft->length ? sz*8.0/(ft->length/ft->signal.rate)/1000.0 : 0);
  }
  fprintf(stderr, "Sample Encoding: %s\n", sox_encoding_name(ft->encoding.encoding));
  fprintf(stderr, "Endian Type    : %s\n", ft->encoding.opposite_endian ? "big" : "little");
  fprintf(stderr, "Reverse Nibbles: %s\n", ft->encoding.reverse_nibbles ? "yes" : "no");
  fprintf(stderr, "Reverse Bits   : %s\n", ft->encoding.reverse_bits ? "yes" : "no");
  if (ft->encoding.comment) fprintf(stderr, "Comment        : '%s'\n", ft->encoding.comment);
  fprintf(stderr, "\n");
}

int main(int argc, char **argv)
{
  int i, effects_start, nfiles_pos;
  int rc = 0;
  sox_set_argv0(argv[0]);
  if (argc == 1) { print_help(); return 1; }
  if (argc > 1 && (strcmp(argv[1], "--info") == 0 || strcmp(argv[1], "--i") == 0)) {
    int r = run_soxi(argc-2, argv+2);
    return r;
  }
  if (strcmp(sox_basename(argv[0]), "soxi") == 0) return run_soxi(argc-1, argv+1);
  if (sox_globals.verbosity >= 3) printf("%s:      SoX v%s\n", sox_globals.argv0, "14.4.2");
  if (parse_opts(argc-1, argv+1, &effects_start, &nfiles_pos) < 0) return 1;
  /* last fopt with a filename is the output */
  {
    int out_idx = -1;
    for (i = 0; i < nfopts; ++i) if (fopts[i].filename) out_idx = i;
    if (out_idx < 0) { sox_fail("sox: No input filenames specified"); print_help(); return 1; }
    if (out_idx == 0) { sox_fail("sox: No input filenames specified"); print_help(); return 1; }
    {
      /* open inputs */
      sox_format_t *in[64]; int nin = 0;
      sox_signalinfo_t sig; sox_encodinginfo_t enc;
      sox_format_t *out;
      chain_t chain; int nch = 0;
      sox_rate_t maxrate = 0; unsigned maxch = 0, maxprec = 0;
      sox_uint64_t total_len = 0;
      memset(&chain, 0, sizeof(chain));
      memset(&sig, 0, sizeof(sig)); memset(&enc, 0, sizeof(enc));
      for (i = 0; i < out_idx; ++i) {
        if (!fopts[i].filename) continue;
        in[nin] = open_input(fopts[i].filename, fopts[i].type, &fopts[i], 0);
        if (!in[nin]) return 1;
        if (in[nin]->signal.rate > maxrate) maxrate = in[nin]->signal.rate;
        if (in[nin]->signal.channels > maxch) maxch = in[nin]->signal.channels;
        if (in[nin]->signal.precision > maxprec) maxprec = in[nin]->signal.precision;
        total_len += in[nin]->length;
        if (nin > 0) {
          if (fabs(in[nin]->signal.rate - in[0]->signal.rate) > 0.001) {
            if (sox_globals.combine_method == 0 || sox_globals.combine_method == 1) {
              sox_fail("sox: Input files must have the same sample-rate"); return 1;
            } else sox_warn("sox: Input files don't have the same sample-rate");
          }
          if (in[nin]->signal.channels != in[0]->signal.channels) {
            if (sox_globals.combine_method == 0 || sox_globals.combine_method == 1) {
              sox_fail("sox: Input files must have the same # channels"); return 1;
            } else sox_warn("sox: Input files don't have the same # channels");
          }
        }
        if (sox_globals.show_progress) display_file_info(in[nin], 0);
        ++nin;
      }
      if (!nin) { sox_fail("sox: No input filenames specified"); print_help(); return 1; }
      sig.rate = maxrate;
      sig.channels = (sox_globals.combine_method == 4) ? 0 : maxch;
      sig.precision = maxprec;
      if (sox_globals.combine_method == 4) { unsigned k, sum = 0; for (k = 0; k < (unsigned)nin; ++k) sum += in[k]->signal.channels; sig.channels = sum; }
      /* output */
      {
        fopt_t *of = &fopts[out_idx];
        if (of->signal.rate) sig.rate = of->signal.rate;
        if (of->signal.channels) sig.channels = of->signal.channels;
        if (of->bits_given) { sig.precision = sox_precision_for(of->encoding.encoding ? of->encoding.encoding : SOX_ENCODING_UNKNOWN, of->encoding_bits); }
        if (of->encoding.encoding) enc.encoding = of->encoding.encoding;
      }
      (void)enc;
      /* open output */
      out = open_output(fopts[out_idx].filename, fopts[out_idx].type, &fopts[out_idx], &sig);
      if (!out) return 1;
      if (sox_globals.show_progress) display_file_info(out, 1);
      /* build the effect chain */
      {
        sox_signalinfo_t cursig = sig;
        cursig.channels = (sox_globals.combine_method == 4) ? sig.channels : maxch;
        cursig.rate = maxrate;
        for (i = effects_start; i < argc-1; ) {
          char *name = argv[1+i];
          sox_effect_t *e;
          int na = 0, j;
          if (sox_effect_find(name) < 0) { sox_fail("sox: unknown effect `%s'", name); return 1; }
          e = sox_create_effect(name);
          e->in_signal = cursig;
          for (j = i+1; j < argc-1; ++j) {
            if (sox_effect_find(argv[1+j]) >= 0) break;
            effects_args[na++] = argv[1+j];
          }
          if (e->handler->getopts && e->handler->getopts(e, effects_args, na) != SOX_SUCCESS) return 1;
          if (e->handler->start && e->handler->start(e) != SOX_SUCCESS) return 1;
          chain_add(&chain, e);
          cursig = e->out_signal;
          i += 1 + na;
        }
      }
      /* auto rate / channels / dither */
      {
        sox_signalinfo_t cursig = chain.n ? chain.e[chain.n-1]->out_signal : sig;
        if (fabs(cursig.rate - out->signal.rate) > 0.001) {
          sox_effect_t *e = sox_create_effect("rate");
          char *args[2]; int na = 0;
          e->in_signal = cursig;
          out->signal.rate = out->signal.rate;
          if (sox_globals.play_rate_arg) { args[na++] = (char*)sox_globals.play_rate_arg; }
          else { static char buf[64]; sprintf(buf, "%u", (unsigned)(out->signal.rate+0.5)); args[na++] = buf; }
          e->handler->getopts(e, args, na);
          e->handler->start(e);
          chain_add(&chain, e);
          cursig = e->out_signal;
        }
        if (cursig.channels != out->signal.channels) {
          sox_effect_t *e = sox_create_effect("channels");
          char *args[2]; int na = 0; static char buf[16];
          e->in_signal = cursig;
          sprintf(buf, "%u", out->signal.channels);
          args[na++] = buf;
          e->handler->getopts(e, args, na);
          e->handler->start(e);
          chain_add(&chain, e);
          cursig = e->out_signal;
        }
        /* dither */
        if (sox_globals.dither && out->signal.precision < 24) {
          int need = 0;
          for (i = 0; i < chain.n; ++i) if (chain.e[i]->extra > 0) need = 1;
          if (in[0]->signal.precision != out->signal.precision) need = 1;
          if (fopts[out_idx].bits_given) need = 1;
          if (need) {
            sox_effect_t *e = sox_create_effect("dither");
            e->in_signal = cursig;
            e->handler->start(e);
            chain_add(&chain, e);
          }
        }
      }
      if (sox_globals.verbosity >= 3) {
        sox_report("sox: effects chain: input %9uHz %2u channels", (unsigned)(in[0]->signal.rate+0.5), in[0]->signal.channels);
        for (i = 0; i < chain.n; ++i)
          sox_report("sox: effects chain: %-13s %uHz %u channels", chain.e[i]->handler->name,
                     (unsigned)(chain.e[i]->out_signal.rate+0.5), chain.e[i]->out_signal.channels);
        sox_report("sox: effects chain: output %8uHz %2u channels", (unsigned)(out->signal.rate+0.5), out->signal.channels);
      }
      rc = sox_run_chain(in, nin, out, &chain, fopts[out_idx].bits_given);
    }
  }
  return rc;
}
