/* ---------- the effect chain driver ---------- */
typedef struct { sox_effect_t *e[64]; int n; } chain_t;

static void chain_add(chain_t *c, sox_effect_t *e)
{ c->e[c->n++] = e; }

static sox_size_t run_flow(sox_effect_t *e, const sox_sample_t *ib, sox_sample_t *ob, sox_size_t is, sox_size_t os)
{ sox_size_t a = is, b = os;
  e->handler->flow(e, ib, ob, &a, &b);
  return b; }

static void display_file_info(sox_format_t *ft, int is_output)
{
  fprintf(stderr, "\n%s File    : '%s'", is_output ? "Output" : "Input", ft->filename);
  if (strcmp(ft->type, "raw") == 0 && !strchr(ft->filename,'.')) fprintf(stderr, " (raw)");
  fprintf(stderr, "\n");
  fprintf(stderr, "Channels       : %u\n", ft->signal.channels);
