/* pipeline.c -- the audio processing pipeline */
#include "soxint.h"
#include "formats.h"
#include "effects.h"

sox_uint64_t fsize_pub(sox_format_t *ft)
{
  long cur = ftell(ft->fp);
  long end;
  fseek(ft->fp, 0, SEEK_END);
  end = ftell(ft->fp);
  fseek(ft->fp, cur, SEEK_SET);
  return (sox_uint64_t)end;
}

static void progress_line(sox_uint64_t in_samps, sox_uint64_t total, sox_uint64_t out_samps, unsigned clips)
{
  double pct = total ? (double)in_samps/total*100 : 100;
  double tin = total ? in_samps/44100.0 : 0;
  double tout = total ? (total - in_samps)/44100.0 : 0;
  char bar[13];
  int i, pos;
  double frac = pct/100;
  pos = (int)(frac*12);
  for (i = 0; i < 12; ++i) bar[i] = (i < pos) ? '=' : ' ';
  bar[6] = '|'; bar[12] = 0;
  fprintf(stderr, "\rIn:%5.2f%% %02d:%02d:%02d.%02d [%02d:%02d:%02d.%02d] Out:%-5g [%s]        Clip:%-4u    ",
          pct, (int)(tin/3600), (int)(tin/60)%60, (int)tin%60, (int)(tin*100)%100,
          (int)(tout/3600), (int)(tout/60)%60, (int)tout%60, (int)(tout*100)%100,
          out_samps >= 1000 ? (double)out_samps/1000 : (double)out_samps, bar, clips);
  (void)in_samps;
}

sox_format_t * open_output(char const *name, char const *type, fopt_t *fo, sox_signalinfo_t *sig)
{
  sox_format_t *ft = calloc(1, sizeof(sox_format_t));
  int idx;
  FILE *fp;
  if (!strcmp(name,"-")) { fp = stdout; }
  else {
