        { sox_sample_t *t = a; a = b; b = t; }
        cur = a;
        if (r == SOX_EOF) { done = 1; break; }
        if (os == 0 && curlen == 0) break;
      }
      /* the last buffer written to is `a' (after the swap) */
      if (curlen) {
        sox_size_t w = out->handler->write(out, a, curlen);
        (void)w;
        total_out += curlen;
      }
    }
    if (sox_globals.show_progress) progress_line(total_out, total_in, total_out, (unsigned)clips);
  }
  /* drain */
  {
    int k;
    for (k = 0; k < chain->n; ++k) {
      sox_effect_t *e = chain->e[k];
      if (e->handler->drain) {
        sox_size_t os = bufsz*4;
        sox_size_t is = 0;
        int r = e->handler->drain(e, obuf, &os);
        if (os) {
          /* push through the remaining effects */
          sox_sample_t *a = tmp1, *b = tmp2;
          const sox_sample_t *cur = obuf;
          sox_size_t curlen = os;
          int j;
          (void)is;
          for (j = k+1; j < chain->n; ++j) {
            sox_effect_t *e2 = chain->e[j];
            sox_size_t is2 = curlen, os2 = bufsz*4;
            e2->handler->flow(e2, cur, b, &is2, &os2);
            curlen = os2;
            { sox_sample_t *t = a; a = b; b = t; }
            cur = a;
          }
          if (curlen) { out->handler->write(out, a, curlen); total_out += curlen; }
        }
        if (r == SOX_EOF) break;
      }
    }
  }
  if (out->handler->stopwrite) out->handler->stopwrite(out);
  for (i = 0; i < chain->n; ++i) {
    sox_effect_t *e = chain->e[i];
    if (e->clips) sox_warn("%s: %s clipped %llu samples; decrease volume?", e->handler->name, in[0]->filename, (unsigned long long)e->clips);
  }
  {
    sox_size_t oc = 0;
    for (i = 0; i < nin; ++i) oc += 0;
    (void)oc;
  }
  if (out->olength) {
    /* clip warnings */
  }
  if (sox_globals.show_progress) fprintf(stderr, "\nDone.\n");
  free(ibuf); free(obuf); free(tmp1); free(tmp2);
  return 0;
}
PEOF
