new='''static sox_format_t * open_input(char const *name, char const *type, fopt_t *fo, int soxi_mode)
{
  sox_format_t *ft = calloc(1, sizeof(sox_format_t));
  FILE *fp = fopen(name, "rb");
  int idx = -1;
  int r;
  (void)soxi_mode;
  if (!fp) { sox_fail("formats: can't open input file `%s': No such file or directory", name); free(ft); return NULL; }
  ft->fp = fp;
  ft->filename = xstrdup(name);
  ft->mode = 'r';
  if (type) {
    idx = sox_format_find(type);
    if (idx < 0) { sox_fail("formats: can't open input file `%s': unknown file type `%s'", name, type); return NULL; }
  } else {
    char const *guess = sox_format_from_ext(name);
    if (guess) idx = sox_format_find(guess);
  }
  if (idx >= 0) {
    const sox_format_handler_t *h = sox_format_get(idx);
    if (h->startread) {
      rewind(fp);
      sox_clear_error();
      r = h->startread(ft);
      if (r == SOX_SUCCESS) { ft->idx = idx; ft->handler = h; strcpy(ft->type, h->name);
        if (sox_globals.verbosity >= 3 && !type) sox_report("formats: detected file format type `%s'", h->name);
        goto done;
      }
      if (r != SOX_EOF) {
        sox_fail("formats: can't open input file `%s': %s", name, sox_last_error());
        return NULL;
      }
      if (type) { sox_fail("formats: can't open input file `%s': %s", name, sox_last_error()); return NULL; }
    }
    idx = -1;
  }
  idx = sox_format_detect(ft);
  if (idx == -1) { sox_fail("formats: can't determine type of file `%s'", name); return NULL; }
  if (idx == -2) { sox_fail("formats: can't open input file `%s': %s", name, sox_last_error()); return NULL; }
  ft->handler = sox_format_get(idx);
  strcpy(ft->type, ft->handler->name);
  if (sox_globals.verbosity >= 3) sox_report("formats: detected file format type `%s'", ft->type);
done:
  if (fo) {
    if (fo->signal.rate) ft->signal.rate = fo->signal.rate;
    if (fo->signal.channels) ft->signal.channels = fo->signal.channels;
    if (fo->encoding.encoding != SOX_ENCODING_UNKNOWN) {
      ft->encoding.encoding = fo->encoding.encoding;
      if (fo->bits_given) { unsigned p = sox_precision_for(fo->encoding.encoding, fo->encoding_bits);
        ft->encoding.precision = p ? p : 0; }
      else if (!ft->encoding.precision) { unsigned b = sox_default_bits(fo->encoding.encoding);
        ft->encoding.precision = sox_precision_for(fo->encoding.encoding, b); }
    }
    if (fo->encoding.reverse_bits) ft->encoding.reverse_bits = 1;
    if (fo->encoding.reverse_nibbles) ft->encoding.reverse_nibbles = 1;
    if (fo->encoding.opposite_endian == 1) ft->encoding.opposite_endian = 1;
    else if (fo->encoding.opposite_endian == 2) ft->encoding.opposite_endian = !ft->encoding.opposite_endian;
  }
  if (ft->encoding.encoding == SOX_ENCODING_UNKNOWN || ft->signal.precision == 0) {
    sox_fail("formats: bad input format for file `%s': data encoding or sample size was not specified", name);
    return NULL;
  }
  ft->signal.precision = ft->encoding.precision;
  return ft;
}

